insert into source_registry (id,name,homepage,purpose,access_mode,configured,live,license_note,env_vars,adapter,status_note,commercial_restriction,last_checked_at) values ('gbif','GBIF · 全球生物多样性信息网络','https://www.gbif.org/','物种分类骨架、观测记录与地理分布数据','no_key',true,true,'各数据集许可不同（CC0 / CC BY / CC BY-NC 等），逐条记录 datasetKey 与许可。',ARRAY['GBIF_API_BASE']::text[],'lib/adapters/gbif.ts','公开 API 已验证可访问，无需密钥。观测点数据为实时请求。','不同数据集许可不同，商业使用前需逐条核对。','2026-11-13T00:00:00.000Z') on conflict (id) do update set name=excluded.name,configured=excluded.configured,live=excluded.live,status_note=excluded.status_note,license_note=excluded.license_note;
insert into source_registry (id,name,homepage,purpose,access_mode,configured,live,license_note,env_vars,adapter,status_note,commercial_restriction,last_checked_at) values ('inaturalist','iNaturalist','https://www.inaturalist.org/','真实观察记录、物种图片与声音素材','api_key',true,true,'照片/录音逐张标注 CC BY、CC BY-NC、CC BY-NC-SA 等许可与署名要求；标记为 NC 的素材不用于商业用途。',ARRAY['INATURALIST_API_BASE']::text[],'lib/adapters/inaturalist.ts','公开 API 可用于读取；审核与批量同步建议使用 OAuth 应用以获得更高配额。','默认仅按素材自身许可使用；NC 素材禁止商业使用。','2026-11-13T00:00:00.000Z') on conflict (id) do update set name=excluded.name,configured=excluded.configured,live=excluded.live,status_note=excluded.status_note,license_note=excluded.license_note;
insert into source_registry (id,name,homepage,purpose,access_mode,configured,live,license_note,env_vars,adapter,status_note,commercial_restriction,last_checked_at) values ('wikipedia','Wikipedia / Wikidata','https://www.wikipedia.org/','辅助知识核对与结构化物种字段','no_key',true,false,'文本 CC BY-SA 4.0；引用时保留来源链接，不整段复制。','{}'::text[],'lib/adapters/wikipedia.ts','已实现接口适配与署名规则；当前展示内容为编辑整理并经来源链接标注，未开启自动抓取。','CC BY-SA 要求署名与相同方式共享。','2026-11-13T00:00:00.000Z') on conflict (id) do update set name=excluded.name,configured=excluded.configured,live=excluded.live,status_note=excluded.status_note,license_note=excluded.license_note;
