insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('giant-panda')::uuid,'giant-panda','大熊猫','Giant Panda','Ailuropoda melanoleuca',ARRAY['熊猫', '竹熊']::text[],'mammal','哺乳动物','以竹子为生的熊科隐士，也是全球保护合作的标志性物种。','大熊猫是熊科中高度特化的成员，几乎完全以竹子为食。它拥有黑白分明的毛色、伪拇指与强壮的咀嚼肌，栖息于中国中西部山地竹林。野外种群在保护区内缓慢恢复，但栖息地破碎化仍是长期威胁。','体形圆厚，肩高约 60–90 厘米；耳、眼周、肩带与四肢为黑色，其余为白色。前掌有由腕骨特化形成的“伪拇指”，便于抓握竹竿。','多为独居，晨昏活动较频繁，每天花大量时间进食与休息。具有较弱的领域性，通过气味标记交流。幼崽约在 1.5–2 岁后逐渐独立。','以高山竹类为主，占食物组成 99% 以上；偶食小型动物、腐肉与植物其他部分。',ARRAY['植食性']::text[],'中国四川、陕西、甘肃海拔 1,200–3,400 米的温带山地竹林，偏好箭竹与冷杉林下密集竹层。','春季发情，妊娠期约 3–5 个月（存在胚胎滞育），通常每胎 1–2 仔，幼崽出生时约 100 克。',120,180,60,90,70,125,20,30,32,ARRAY['大熊猫的“伪拇指”并非真正的手指，而是腕部籽骨的延长结构。', '为高效咀嚼竹子，它的头骨与下颌肌肉异常发达，臼齿宽大。', '幼崽出生时体重仅为母体的千分之一左右，是哺乳动物中相对最小的新生儿之一。']::text[],'{"base":"#E9E2D3","deep":"#141C18","accent":"#8C9A7C"}'::jsonb,'bear',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='食肉目 Carnivora' and family='熊科 Ursidae' and genus='Ailuropoda' limit 1),'VU'::conservation_status,'unknown'::population_trend,2016,'IUCN 2016 年评估为易危；中国第四次全国大熊猫调查（2011–2014）记录野生个体 1,864 只。后续种群数字需以官方调查与 IUCN 更新为准。',ARRAY['栖息地破碎化', '竹子开花导致的局域食物短缺', '气候变化影响竹林分布', '人类活动干扰']::text[],ARRAY['建立自然保护区网络', '生态廊道建设', '圈养繁育与野化放归研究', '社区共管与生态补偿']::text[],ARRAY['东亚']::text[],ARRAY['中国']::text[],ARRAY['温带山地竹林', '亚高山针叶林']::text[],'自然分布仅限中国中部山地；境外个体均为借展或圈养。',2433399,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Ailuropoda%20melanoleuca','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
