insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='giant-panda'),'fun_fact','趣闻 2','为高效咀嚼竹子，它的头骨与下颌肌肉异常发达，臼齿宽大。','IUCN Red List','https://www.iucnredlist.org/search?query=Ailuropoda%20melanoleuca','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='giant-panda'),'fun_fact','趣闻 3','幼崽出生时体重仅为母体的千分之一左右，是哺乳动物中相对最小的新生儿之一。','IUCN Red List','https://www.iucnredlist.org/search?query=Ailuropoda%20melanoleuca','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='giant-panda'),'IUCN','VU'::conservation_status,'unknown'::population_trend,2016,'IUCN 2016 年评估为易危；中国第四次全国大熊猫调查（2011–2014）记录野生个体 1,864 只。后续种群数字需以官方调查与 IUCN 更新为准。',ARRAY['栖息地破碎化', '竹子开花导致的局域食物短缺', '气候变化影响竹林分布', '人类活动干扰']::text[],ARRAY['建立自然保护区网络', '生态廊道建设', '圈养繁育与野化放归研究', '社区共管与生态补偿']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Ailuropoda%20melanoleuca','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('tiger')::uuid,'tiger','虎','Tiger','Panthera tigris',ARRAY['老虎', '东北虎', '孟加拉虎']::text[],'mammal','哺乳动物','现存最大的猫科动物，独行于亚洲森林的顶级捕食者。','虎是亚洲大型猫科动物的代表，条纹如同指纹般独一无二。不同亚种在体型与栖息地上差异显著。尽管保护投入持续增加，偷猎与栖息地丧失仍使其种群整体呈下降趋势。','体长可达 3 米以上（含尾），橙黄色被毛配黑色条纹，腹部与面部内侧偏白；耳背有显著白斑。','多为独居，领域范围大，雄性领域常与多只雌性重叠。善游泳，多在夜间捕猎，靠伏击而非长距离追逐。','以大型有蹄类为主，如野猪、鹿、野牛；也会捕食较小猎物。',ARRAY['肉食性']::text[],'从热带雨林、季风林到针阔混交林与红树林，依赖充足猎物与隐蔽覆盖。','妊娠期约 93–112 天，每胎 1–4 仔，幼崽跟随母虎约 1.5–2 年。',190,330,70,120,100,300,15,20,60,ARRAY['每只虎的条纹排列独一无二，可用于个体识别。', '虎的舌面具有角质化乳突，有助于从骨头上刮取肉。', '虎喜欢水，是猫科中少数经常主动游泳的成员。']::text[],'{"base":"#D9B26A","deep":"#1A1611","accent":"#C26A3A"}'::jsonb,'cat',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='食肉目 Carnivora' and family='猫科 Felidae' and genus='Panthera' limit 1),'EN'::conservation_status,'decreasing'::population_trend,2015,'IUCN 2015 年评估为濒危。全球野生种群数量常被引用为约 3,900–5,000 只，需以 IUCN 与各国官方监测为准。',ARRAY['偷猎与非法贸易', '栖息地丧失与破碎化', '猎物资源下降', '人虎冲突']::text[],ARRAY['反盗猎巡护', '虎分布国跨境合作', '栖息地连通性修复', '社区补偿与替代生计']::text[],ARRAY['南亚', '东南亚', '东亚', '俄罗斯远东']::text[],ARRAY['印度', '尼泊尔', '不丹', '孟加拉国', '俄罗斯', '中国', '泰国', '马来西亚', '印度尼西亚']::text[],ARRAY['热带雨林', '季风林', '温带针阔混交林', '红树林']::text[],'历史分布范围大幅收缩；当前分布高度破碎，亚种划分仍存在分类学讨论。',5219416,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Panthera%20tigris','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
