insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='tiger'),'fun_fact','趣闻 2','虎的舌面具有角质化乳突，有助于从骨头上刮取肉。','IUCN Red List','https://www.iucnredlist.org/search?query=Panthera%20tigris','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='tiger'),'fun_fact','趣闻 3','虎喜欢水，是猫科中少数经常主动游泳的成员。','IUCN Red List','https://www.iucnredlist.org/search?query=Panthera%20tigris','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='tiger'),'IUCN','EN'::conservation_status,'decreasing'::population_trend,2015,'IUCN 2015 年评估为濒危。全球野生种群数量常被引用为约 3,900–5,000 只，需以 IUCN 与各国官方监测为准。',ARRAY['偷猎与非法贸易', '栖息地丧失与破碎化', '猎物资源下降', '人虎冲突']::text[],ARRAY['反盗猎巡护', '虎分布国跨境合作', '栖息地连通性修复', '社区补偿与替代生计']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Panthera%20tigris','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('snow-leopard')::uuid,'snow-leopard','雪豹','Snow Leopard','Panthera uncia',ARRAY['雪山之王', '艾叶豹']::text[],'mammal','哺乳动物','高原岩壁上的幽灵，以长尾平衡身体，也以隐秘著称。','雪豹分布于中亚高山地带，厚实的被毛与长尾帮助它在严寒和陡峭地形中生存。它被称为“山地生态系统的旗舰物种”，其种群状况长期因难以观测而存在较大不确定性。','灰白色被毛配深色玫瑰斑，尾长几乎等于体长，耳小而圆，脚掌宽大具毛垫。','独居、晨昏与夜间活动，领域范围可达数百平方公里。善于在悬崖与碎石坡伏击猎物。','以岩羊、盘羊等山地有蹄类为主，也捕食旱獭、兔类与鸟类。',ARRAY['肉食性']::text[],'中亚高山裸岩、高山草甸与灌丛，通常海拔 3,000–4,500 米。','发情多在冬季，妊娠期约 90–105 天，每胎 1–3 仔。',90,130,55,65,22,55,15,18,64,ARRAY['雪豹的尾巴可达体长，既是平衡器官，也可在休息时包裹身体保暖。', '它不能像狮虎那样大声吼叫，但能发出呼噜声与哨音。', '雪豹的脚掌下方有浓密毛垫，增加雪地抓地力。']::text[],'{"base":"#D7D9D2","deep":"#1B2422","accent":"#7C8F8A"}'::jsonb,'cat',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='食肉目 Carnivora' and family='猫科 Felidae' and genus='Panthera' limit 1),'VU'::conservation_status,'decreasing'::population_trend,2017,'IUCN 2017 年评估为易危。全球野外种群估计约 4,000–6,500 只，估计区间宽且不确定性高。',ARRAY['偷猎', '栖息地退化', '猎物减少', '气候变化', '人兽冲突']::text[],ARRAY['跨国保护计划', '社区巡护与补偿', '反盗猎监测', '高原生态廊道规划']::text[],ARRAY['中亚', '南亚', '青藏高原']::text[],ARRAY['中国', '蒙古', '尼泊尔', '印度', '巴基斯坦', '阿富汗', '塔吉克斯坦', '吉尔吉斯斯坦']::text[],ARRAY['高山裸岩', '高山草甸', '亚高山灌丛']::text[],'分布区跨越 12 个国家的高山系统，实际边界仍依赖红外相机与遗传调查。',5787213,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Panthera%20uncia','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
