insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='snow-leopard'),'fun_fact','趣闻 2','它不能像狮虎那样大声吼叫，但能发出呼噜声与哨音。','IUCN Red List','https://www.iucnredlist.org/search?query=Panthera%20uncia','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='snow-leopard'),'fun_fact','趣闻 3','雪豹的脚掌下方有浓密毛垫，增加雪地抓地力。','IUCN Red List','https://www.iucnredlist.org/search?query=Panthera%20uncia','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='snow-leopard'),'IUCN','VU'::conservation_status,'decreasing'::population_trend,2017,'IUCN 2017 年评估为易危。全球野外种群估计约 4,000–6,500 只，估计区间宽且不确定性高。',ARRAY['偷猎', '栖息地退化', '猎物减少', '气候变化', '人兽冲突']::text[],ARRAY['跨国保护计划', '社区巡护与补偿', '反盗猎监测', '高原生态廊道规划']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Panthera%20uncia','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('african-elephant')::uuid,'african-elephant','非洲草原象','African Savanna Elephant','Loxodonta africana',ARRAY['非洲象', '草原象']::text[],'mammal','哺乳动物','陆地上最大的现存动物，也是生态系统的“工程师”。','非洲草原象以巨大的体重、灵活的象鼻与复杂的社会结构著称。它们推倒树木、挖掘水源、传播种子，深刻塑造稀树草原景观。盗猎与栖息地碎片化是主要威胁。','肩高可达 4 米，体重 4–7 吨；大耳用于散热，鼻端有两个指状突起，雌雄均有象牙（雄性更长）。','以母系家族群为核心，年长雌象领导群体；成年雄象多独居或组成松散群体。具有复杂的低频交流与长期记忆。','以草、树叶、树皮、果实为主，日食量可达体重的 4%–6%。',ARRAY['植食性']::text[],'撒哈拉以南非洲的稀树草原、灌丛、湿地与森林边缘。','妊娠期约 22 个月，为陆生哺乳动物中最长；通常每胎 1 仔，间隔 3–5 年。',600,750,300,400,4000,7000,60,70,40,ARRAY['象鼻约有 4 万束肌肉，没有骨骼，可同时完成吸水、抓握与发声。', '象群会围绕死去的同伴停留，表现出类似哀悼的行为。', '大象能发出人类听不到的低频声，用于远距离沟通。']::text[],'{"base":"#B9A48B","deep":"#241E19","accent":"#8A6F55"}'::jsonb,'elephant',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='长鼻目 Proboscidea' and family='象科 Elephantidae' and genus='Loxodonta' limit 1),'EN'::conservation_status,'decreasing'::population_trend,2021,'IUCN 2021 年将非洲草原象评估为濒危。种群数量与趋势存在区域性差异，需参考 IUCN 非洲象数据库。',ARRAY['象牙盗猎', '栖息地丧失', '人象冲突', '干旱与气候变化']::text[],ARRAY['跨境保护地网络', '反盗猎行动', '社区共管', '生态廊道与水源保护']::text[],ARRAY['撒哈拉以南非洲']::text[],ARRAY['肯尼亚', '坦桑尼亚', '博茨瓦纳', '南非', '津巴布韦', '赞比亚', '纳米比亚', '乌干达']::text[],ARRAY['稀树草原', '灌丛', '湿地', '森林边缘']::text[],'分布国家众多，区域种群趋势差异明显。',2435350,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Loxodonta%20africana','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
