insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='african-elephant'),'fun_fact','趣闻 2','象群会围绕死去的同伴停留，表现出类似哀悼的行为。','IUCN Red List','https://www.iucnredlist.org/search?query=Loxodonta%20africana','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='african-elephant'),'fun_fact','趣闻 3','大象能发出人类听不到的低频声，用于远距离沟通。','IUCN Red List','https://www.iucnredlist.org/search?query=Loxodonta%20africana','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='african-elephant'),'IUCN','EN'::conservation_status,'decreasing'::population_trend,2021,'IUCN 2021 年将非洲草原象评估为濒危。种群数量与趋势存在区域性差异，需参考 IUCN 非洲象数据库。',ARRAY['象牙盗猎', '栖息地丧失', '人象冲突', '干旱与气候变化']::text[],ARRAY['跨境保护地网络', '反盗猎行动', '社区共管', '生态廊道与水源保护']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Loxodonta%20africana','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('blue-whale')::uuid,'blue-whale','蓝鲸','Blue Whale','Balaenoptera musculus',ARRAY['蓝灰鲸']::text[],'mammal','哺乳动物','地球历史上已知最大的动物，心跳声可传很远。','蓝鲸是须鲸中体型最大的成员，依靠鲸须滤食磷虾。20 世纪的商业捕鲸使其数量骤减，如今部分种群有所恢复，但航运撞击、渔具缠绕与海洋噪声仍是威胁。','体长可达 24–30 米，背部蓝灰色带斑驳纹理，腹部较浅；喷气孔可喷出高达 9 米的水柱。','多独自或成对活动，长距离迁徙于觅食场与繁殖场之间。以低频叫声进行远距离交流。','几乎完全以磷虾为食，日摄食量可达数吨。',ARRAY['滤食性']::text[],'全球海洋，从极地到热带，主要在上升流丰富的冷水中觅食。','妊娠期约 10–12 个月，通常每 2–3 年产 1 仔，新生幼鲸体长约 7 米。',2400,3000,NULL,NULL,50000,150000,80,90,48,ARRAY['蓝鲸的心脏重可达 180 公斤以上，是已知最大的动物器官之一。', '蓝鲸的叫声可达约 180 分贝，在海洋中传播数百公里。', '幼鲸出生后每天可增重约 90 公斤。']::text[],'{"base":"#8FA6AD","deep":"#0C1B24","accent":"#3E6B7A"}'::jsonb,'whale',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='鲸偶蹄目 Cetartiodactyla' and family='须鲸科 Balaenopteridae' and genus='Balaenoptera' limit 1),'EN'::conservation_status,'increasing'::population_trend,2018,'IUCN 2018 年评估为濒危。部分区域种群呈恢复迹象，但全球总数与亚种状况差异很大。',ARRAY['船只撞击', '渔具缠绕', '海洋噪声', '气候变化影响磷虾', '海洋污染']::text[],ARRAY['航运改道与限速', '鲸类监测', '国际捕鲸管制', '海洋保护区网络']::text[],ARRAY['全球海洋']::text[],ARRAY['多个沿海国家管辖海域']::text[],ARRAY['大洋', '极地海域', '上升流区']::text[],'分布跨越各大洋；具体种群划分与迁徙路线仍在研究中。',2440735,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Balaenoptera%20musculus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='blue-whale'),'fun_fact','趣闻 1','蓝鲸的心脏重可达 180 公斤以上，是已知最大的动物器官之一。','IUCN Red List','https://www.iucnredlist.org/search?query=Balaenoptera%20musculus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='blue-whale'),'fun_fact','趣闻 2','蓝鲸的叫声可达约 180 分贝，在海洋中传播数百公里。','IUCN Red List','https://www.iucnredlist.org/search?query=Balaenoptera%20musculus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='blue-whale'),'fun_fact','趣闻 3','幼鲸出生后每天可增重约 90 公斤。','IUCN Red List','https://www.iucnredlist.org/search?query=Balaenoptera%20musculus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='blue-whale'),'IUCN','EN'::conservation_status,'increasing'::population_trend,2018,'IUCN 2018 年评估为濒危。部分区域种群呈恢复迹象，但全球总数与亚种状况差异很大。',ARRAY['船只撞击', '渔具缠绕', '海洋噪声', '气候变化影响磷虾', '海洋污染']::text[],ARRAY['航运改道与限速', '鲸类监测', '国际捕鲸管制', '海洋保护区网络']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Balaenoptera%20musculus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('giraffe')::uuid,'giraffe','长颈鹿','Giraffe','Giraffa camelopardalis',ARRAY['长颈鹿']::text[],'mammal','哺乳动物','把高度变成生态位的反刍动物，斑纹因地域而异。','长颈鹿以极长的颈部和腿在稀树草原上取食高处的树叶。它的颈部只有七枚颈椎，与人类相同，但每节极度延长。分类学近年倾向将长颈鹿拆分为多个独立物种，本馆暂采用传统广义种名并标注待核验。','肩高 3–3.3 米，头顶可达 5.5 米；网纹或斑块状花纹，头顶有皮骨角。','群居但结构松散，雄性通过“颈击”竞争。睡眠时间极短，警觉性高。','以金合欢等树木叶片与嫩枝为主，偶尔饮水。',ARRAY['植食性']::text[],'非洲稀树草原、开阔林地与灌丛。','妊娠期约 15 个月，通常每胎 1 仔，幼崽出生即可站立。',400,550,400,550,700,1200,20,25,60,ARRAY['长颈鹿与人类一样只有 7 节颈椎，但每节可长达 25 厘米。', '它的舌头呈蓝紫色，长约 45 厘米，可卷取带刺的树叶。', '长颈鹿每天睡眠时间常少于 2 小时。']::text[],'{"base":"#C99A5D","deep":"#2B1D11","accent":"#8B5A2B"}'::jsonb,'giraffe',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='偶蹄目 Artiodactyla' and family='长颈鹿科 Giraffidae' and genus='Giraffa' limit 1),'VU'::conservation_status,'decreasing'::population_trend,2016,'IUCN 2016 年将广义长颈鹿评估为易危。2025 年前后分类学修订将长颈鹿拆分为多个物种，保护等级需按新分类重新核对。',ARRAY['栖息地丧失', '盗猎', '生态孤岛化', '气候变化']::text[],ARRAY['跨境种群监测', '保护区网络', '社区保护项目', '种群遗传研究']::text[],ARRAY['撒哈拉以南非洲']::text[],ARRAY['肯尼亚', '坦桑尼亚', '南非', '纳米比亚', '博茨瓦纳', '赞比亚', '津巴布韦']::text[],ARRAY['稀树草原', '开阔林地', '灌丛']::text[],'分布高度碎片化，各地区种群斑纹与遗传结构差异显著。',2441205,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Giraffa%20camelopardalis','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
