insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='giraffe'),'fun_fact','趣闻 2','它的舌头呈蓝紫色，长约 45 厘米，可卷取带刺的树叶。','IUCN Red List','https://www.iucnredlist.org/search?query=Giraffa%20camelopardalis','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='giraffe'),'fun_fact','趣闻 3','长颈鹿每天睡眠时间常少于 2 小时。','IUCN Red List','https://www.iucnredlist.org/search?query=Giraffa%20camelopardalis','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='giraffe'),'IUCN','VU'::conservation_status,'decreasing'::population_trend,2016,'IUCN 2016 年将广义长颈鹿评估为易危。2025 年前后分类学修订将长颈鹿拆分为多个物种，保护等级需按新分类重新核对。',ARRAY['栖息地丧失', '盗猎', '生态孤岛化', '气候变化']::text[],ARRAY['跨境种群监测', '保护区网络', '社区保护项目', '种群遗传研究']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Giraffa%20camelopardalis','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('red-panda')::uuid,'red-panda','小熊猫','Red Panda','Ailurus fulgens',ARRAY['红熊猫', '火狐']::text[],'mammal','哺乳动物','名字里有“熊猫”，却不是熊猫；树栖的竹食者。','小熊猫是喜马拉雅东部与横断山区特有的树栖食肉目动物，独立成科。它以红褐色被毛、环状尾与灵活的攀爬能力著称，野外种群因栖息地丧失而持续下降。','体长约 50–65 厘米，尾长 30–50 厘米；红褐色背部、深色腹部与四肢，面部有白色斑纹。','以晨昏与夜间活动为主，善爬树，常用尾巴保持平衡。多为独居，通过气味标记与叫声交流。','以竹叶、竹笋为主，也吃果实、昆虫与鸟卵。',ARRAY['植食性', '杂食性']::text[],'海拔 2,200–4,800 米的温带山地竹林与针阔混交林。','春季发情，妊娠期约 130 天，每胎 1–4 仔。',50,65,25,35,3,6.2,8,14,NULL,ARRAY['小熊猫的尾环纹路可用于个体识别。', '它有一个特化的腕骨突起，帮助抓握竹枝。', '受到惊吓时会站立并举起前肢，但这是威吓姿态而非“投降”。']::text[],'{"base":"#C8693E","deep":"#2A120A","accent":"#E2B178"}'::jsonb,'bear',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='食肉目 Carnivora' and family='小熊猫科 Ailuridae' and genus='Ailurus' limit 1),'EN'::conservation_status,'decreasing'::population_trend,2015,'IUCN 2015 年评估为濒危。全球野外种群估计不足 10,000 只，属于较早且不确定性较高的估计。',ARRAY['栖息地丧失与破碎化', '偷猎', '犬瘟热等疾病', '气候变化']::text[],ARRAY['保护区建设', '反盗猎巡护', '圈养繁育', '社区教育']::text[],ARRAY['喜马拉雅东部', '横断山区']::text[],ARRAY['中国', '尼泊尔', '不丹', '印度', '缅甸']::text[],ARRAY['山地竹林', '针阔混交林']::text[],'分布区狭长且碎片化，种群密度低。',5219446,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Ailurus%20fulgens','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
