insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='red-panda'),'fun_fact','趣闻 2','它有一个特化的腕骨突起，帮助抓握竹枝。','IUCN Red List','https://www.iucnredlist.org/search?query=Ailurus%20fulgens','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='red-panda'),'fun_fact','趣闻 3','受到惊吓时会站立并举起前肢，但这是威吓姿态而非“投降”。','IUCN Red List','https://www.iucnredlist.org/search?query=Ailurus%20fulgens','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='red-panda'),'IUCN','EN'::conservation_status,'decreasing'::population_trend,2015,'IUCN 2015 年评估为濒危。全球野外种群估计不足 10,000 只，属于较早且不确定性较高的估计。',ARRAY['栖息地丧失与破碎化', '偷猎', '犬瘟热等疾病', '气候变化']::text[],ARRAY['保护区建设', '反盗猎巡护', '圈养繁育', '社区教育']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Ailurus%20fulgens','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('axolotl')::uuid,'axolotl','墨西哥钝口螈','Axolotl','Ambystoma mexicanum',ARRAY['六角恐龙', '美西螈']::text[],'amphibian','两栖动物','终生保留幼体特征，能再生肢体的“水中精灵”。','墨西哥钝口螈是墨西哥城南部霍奇米尔科湖区的特有蝾螈，因幼态延续而终生保留外鳃。它拥有强大的肢体与脊髓再生能力，是再生医学研究的重要模型。野生种群因水体污染与外来鱼类而极危。','体长 15–30 厘米，体色多样；头侧三对外鳃，背鳍自头后延伸至尾端。','水栖，白天隐藏于水草与洞穴，夜间活动。以吸食方式捕食。','水生无脊椎动物、小鱼、蝌蚪与甲壳类。',ARRAY['肉食性']::text[],'高海拔淡水湖泊与运河，水温较低、溶氧较丰富、水草密集。','体外受精，雌性可产数百枚卵，约 2 周孵化。',15,30,NULL,NULL,0.06,0.3,10,15,NULL,ARRAY['它终生保留幼体形态（幼态延续），外鳃是呼吸器官。', '可再生四肢、尾巴、脊髓甚至部分心脏组织。', '野外仅分布于墨西哥城周边极有限的运河与湿地。']::text[],'{"base":"#D9A9A2","deep":"#2A1517","accent":"#B45C63"}'::jsonb,'amphibian',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='两栖纲 Amphibia' and order_name='有尾目 Caudata' and family='钝口螈科 Ambystomatidae' and genus='Ambystoma' limit 1),'CR'::conservation_status,'decreasing'::population_trend,2020,'IUCN 2020 年评估为极危。野外种群调查显示密度极低，具体数量需以 IUCN 与墨西哥官方监测为准。',ARRAY['水体污染', '外来鱼类捕食', '城市化', '栖息地丧失', '宠物贸易采集']::text[],ARRAY['湿地修复', '外来物种清除', '就地保护与人工繁育', '社区参与']::text[],ARRAY['中美洲']::text[],ARRAY['墨西哥']::text[],ARRAY['淡水湖泊', '运河与湿地']::text[],'野生分布仅限墨西哥城南部霍奇米尔科及周边运河水系。',2431950,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Ambystoma%20mexicanum','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='axolotl'),'fun_fact','趣闻 1','它终生保留幼体形态（幼态延续），外鳃是呼吸器官。','IUCN Red List','https://www.iucnredlist.org/search?query=Ambystoma%20mexicanum','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='axolotl'),'fun_fact','趣闻 2','可再生四肢、尾巴、脊髓甚至部分心脏组织。','IUCN Red List','https://www.iucnredlist.org/search?query=Ambystoma%20mexicanum','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='axolotl'),'fun_fact','趣闻 3','野外仅分布于墨西哥城周边极有限的运河与湿地。','IUCN Red List','https://www.iucnredlist.org/search?query=Ambystoma%20mexicanum','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='axolotl'),'IUCN','CR'::conservation_status,'decreasing'::population_trend,2020,'IUCN 2020 年评估为极危。野外种群调查显示密度极低，具体数量需以 IUCN 与墨西哥官方监测为准。',ARRAY['水体污染', '外来鱼类捕食', '城市化', '栖息地丧失', '宠物贸易采集']::text[],ARRAY['湿地修复', '外来物种清除', '就地保护与人工繁育', '社区参与']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Ambystoma%20mexicanum','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('galapagos-tortoise')::uuid,'galapagos-tortoise','加拉帕戈斯象龟','Galápagos Giant Tortoise','Chelonoidis niger',ARRAY['加拉帕戈斯陆龟']::text[],'reptile','爬行动物','岛屿演化的活化石，壳形随岛屿气候分化。','加拉帕戈斯象龟是加拉帕戈斯群岛的特有巨型陆龟，不同岛屿的种群在壳形与体型上存在差异。历史上因捕鲸船采集而锐减，如今在人工繁育与外来物种控制下部分种群有所恢复。','体重可达 400 公斤以上，背甲高隆或马鞍形；颈部皮肤褶皱明显，四肢粗壮。','行动缓慢，喜在泥沼中降温；具有季节性迁移习性。','以草、仙人掌、果实与灌木叶为主。',ARRAY['植食性']::text[],'加拉帕戈斯群岛的干旱灌丛、草原与火山高地。','交配季节多在雨季，每窝可产 2–16 枚卵，孵化期约 4–8 个月。',120,180,NULL,NULL,150,400,80,120,0.3,ARRAY['不同岛屿的象龟壳形不同，被认为与取食高度和气候相关。', '象龟可通过长距离迁徙寻找水源，并沿固定路径行走。', '圈养个体“孤独的乔治”于 2012 年死亡，平塔岛种群随之灭绝。']::text[],'{"base":"#8E8A70","deep":"#1E2117","accent":"#5F6B4A"}'::jsonb,'reptile',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='爬行纲 Reptilia' and order_name='龟鳖目 Testudines' and family='陆龟科 Testudinidae' and genus='Chelonoidis' limit 1),'VU'::conservation_status,'increasing'::population_trend,2015,'IUCN 2015 年评估为易危。不同岛屿种群状况差异极大，部分种群极危甚至灭绝。',ARRAY['外来物种捕食与竞争', '栖息地退化', '历史捕猎', '疾病', '火山活动']::text[],ARRAY['人工繁育与再引入', '外来山羊与鼠类清除', '种群监测', '国家公园管理']::text[],ARRAY['东太平洋加拉帕戈斯群岛']::text[],ARRAY['厄瓜多尔']::text[],ARRAY['干旱灌丛', '火山高地草原']::text[],'仅分布于加拉帕戈斯群岛，多个岛屿种群独立演化。',9527499,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Chelonoidis%20niger','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='galapagos-tortoise'),'fun_fact','趣闻 1','不同岛屿的象龟壳形不同，被认为与取食高度和气候相关。','IUCN Red List','https://www.iucnredlist.org/search?query=Chelonoidis%20niger','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='galapagos-tortoise'),'fun_fact','趣闻 2','象龟可通过长距离迁徙寻找水源，并沿固定路径行走。','IUCN Red List','https://www.iucnredlist.org/search?query=Chelonoidis%20niger','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='galapagos-tortoise'),'fun_fact','趣闻 3','圈养个体“孤独的乔治”于 2012 年死亡，平塔岛种群随之灭绝。','IUCN Red List','https://www.iucnredlist.org/search?query=Chelonoidis%20niger','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='galapagos-tortoise'),'IUCN','VU'::conservation_status,'increasing'::population_trend,2015,'IUCN 2015 年评估为易危。不同岛屿种群状况差异极大，部分种群极危甚至灭绝。',ARRAY['外来物种捕食与竞争', '栖息地退化', '历史捕猎', '疾病', '火山活动']::text[],ARRAY['人工繁育与再引入', '外来山羊与鼠类清除', '种群监测', '国家公园管理']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Chelonoidis%20niger','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('emperor-penguin')::uuid,'emperor-penguin','帝企鹅','Emperor Penguin','Aptenodytes forsteri',ARRAY['皇帝企鹅']::text[],'bird','鸟类','在南极严冬繁殖，由雄性承担漫长的孵卵任务。','帝企鹅是现存体型最大的企鹅，在南极海冰上繁殖。雄性在严寒中持续孵卵数周，依靠群体取暖。海冰变化与猎物分布变化是其面临的主要威胁。','体高可达 1.2 米，背部黑色、腹部白色，颈部与耳部有黄色至橙色斑块。','高度社会化的海鸟，繁殖期形成大规模群体；雄鸟通过叫声识别配偶。','鱼类、磷虾与头足类。',ARRAY['肉食性']::text[],'南极大陆边缘海冰与周边海域。','每对每年繁殖一次，雌鸟产 1 枚卵后由雄鸟孵化约 65 天，期间雄鸟不进食。',100,130,100,130,22,45,15,20,9,ARRAY['帝企鹅可潜水超过 500 米，单次潜水可达 20 分钟以上。', '雄鸟孵卵期间会失去约一半体重。', '企鹅群体通过拥挤与交替位置来减少热量散失。']::text[],'{"base":"#B8C4C9","deep":"#0B1720","accent":"#D7A93F"}'::jsonb,'bird',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='鸟纲 Aves' and order_name='企鹅目 Sphenisciformes' and family='企鹅科 Spheniscidae' and genus='Aptenodytes' limit 1),'NT'::conservation_status,'decreasing'::population_trend,2022,'IUCN 2022 年评估为近危。种群预测受海冰变化影响较大，需持续监测。',ARRAY['海冰减少', '猎物分布变化', '气候变化', '渔业竞争', '研究站干扰']::text[],ARRAY['南极条约体系保护', '种群遥感监测', '海洋保护区倡议', '气候政策推动']::text[],ARRAY['南极洲及周边海域']::text[],ARRAY['南极洲（无主权国家）']::text[],ARRAY['南极海冰', '极地海洋']::text[],'繁殖地环绕南极大陆海岸，具体殖民地受海冰条件影响。',2481661,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Aptenodytes%20forsteri','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='emperor-penguin'),'fun_fact','趣闻 1','帝企鹅可潜水超过 500 米，单次潜水可达 20 分钟以上。','IUCN Red List','https://www.iucnredlist.org/search?query=Aptenodytes%20forsteri','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='emperor-penguin'),'fun_fact','趣闻 2','雄鸟孵卵期间会失去约一半体重。','IUCN Red List','https://www.iucnredlist.org/search?query=Aptenodytes%20forsteri','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='emperor-penguin'),'fun_fact','趣闻 3','企鹅群体通过拥挤与交替位置来减少热量散失。','IUCN Red List','https://www.iucnredlist.org/search?query=Aptenodytes%20forsteri','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='emperor-penguin'),'IUCN','NT'::conservation_status,'decreasing'::population_trend,2022,'IUCN 2022 年评估为近危。种群预测受海冰变化影响较大，需持续监测。',ARRAY['海冰减少', '猎物分布变化', '气候变化', '渔业竞争', '研究站干扰']::text[],ARRAY['南极条约体系保护', '种群遥感监测', '海洋保护区倡议', '气候政策推动']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Aptenodytes%20forsteri','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('monarch-butterfly')::uuid,'monarch-butterfly','帝王蝶','Monarch Butterfly','Danaus plexippus',ARRAY['黑脉金斑蝶', '君主斑蝶']::text[],'insect','昆虫','跨代完成数千公里迁徙的鳞翅目旅行者。','帝王蝶以橙色翅面与黑色翅脉著称，北美种群每年进行跨越大陆的迁徙。迁徙世代依靠体内时钟与太阳方位定向。IUCN 于 2022 年将迁徙亚种评估为濒危。','翼展约 9–10 厘米，橙色翅面配黑色翅脉与白点；幼虫具黑白黄相间条纹。','成虫吸食花蜜；迁徙世代进入滞育状态，寿命显著延长。','幼虫专食马利筋属植物；成虫取食多种花蜜。',ARRAY['植食性']::text[],'北美草原、农田边缘、花园与越冬山地森林。','雌蝶在寄主植物上产卵，卵约 3–8 天孵化；一年可经历多代。',NULL,NULL,NULL,NULL,0.0005,0.001,0.1,0.8,20,ARRAY['迁徙世代可飞行数千公里，从加拿大抵达墨西哥中部越冬地。', '帝王蝶对马利筋中的毒素具有耐受性，并将毒素储存在体内。', '翅膀上的鳞片结构产生橙色与黑色，是警戒色。']::text[],'{"base":"#D98A2B","deep":"#241208","accent":"#F2C14E"}'::jsonb,'insect',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='节肢动物门 Arthropoda' and class_name='昆虫纲 Insecta' and order_name='鳞翅目 Lepidoptera' and family='蛱蝶科 Nymphalidae' and genus='Danaus' limit 1),'EN'::conservation_status,'decreasing'::population_trend,2022,'IUCN 2022 年将迁徙亚种 Danaus plexippus plexippus 评估为濒危；非迁徙种群未纳入同一评估。',ARRAY['越冬森林砍伐', '寄主植物减少', '农药使用', '气候变化', '极端天气']::text[],ARRAY['越冬地保护', '马利筋种植与栖息地恢复', '农药减量', '公民科学监测']::text[],ARRAY['北美洲', '中美洲']::text[],ARRAY['加拿大', '美国', '墨西哥', '古巴', '澳大利亚（引入种群）']::text[],ARRAY['温带草原', '农田边缘', '山地针叶林']::text[],'北美迁徙种群与中美洲、南美及大洋洲的非迁徙种群需分开评估。',5133088,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Danaus%20plexippus%20plexippus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='monarch-butterfly'),'fun_fact','趣闻 1','迁徙世代可飞行数千公里，从加拿大抵达墨西哥中部越冬地。','IUCN Red List','https://www.iucnredlist.org/search?query=Danaus%20plexippus%20plexippus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='monarch-butterfly'),'fun_fact','趣闻 2','帝王蝶对马利筋中的毒素具有耐受性，并将毒素储存在体内。','IUCN Red List','https://www.iucnredlist.org/search?query=Danaus%20plexippus%20plexippus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='monarch-butterfly'),'fun_fact','趣闻 3','翅膀上的鳞片结构产生橙色与黑色，是警戒色。','IUCN Red List','https://www.iucnredlist.org/search?query=Danaus%20plexippus%20plexippus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='monarch-butterfly'),'IUCN','EN'::conservation_status,'decreasing'::population_trend,2022,'IUCN 2022 年将迁徙亚种 Danaus plexippus plexippus 评估为濒危；非迁徙种群未纳入同一评估。',ARRAY['越冬森林砍伐', '寄主植物减少', '农药使用', '气候变化', '极端天气']::text[],ARRAY['越冬地保护', '马利筋种植与栖息地恢复', '农药减量', '公民科学监测']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Danaus%20plexippus%20plexippus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('green-sea-turtle')::uuid,'green-sea-turtle','绿海龟','Green Sea Turtle','Chelonia mydas',ARRAY['绿龟', '海龟']::text[],'reptile','爬行动物','以海草为食的海洋园艺师，跨洋迁徙数千公里。','绿海龟因体脂呈绿色而得名，是唯一以海草为主食的海龟。成年个体在觅食场与筑巢海滩之间长距离迁徙。渔具缠绕、海岸开发与海洋塑料是主要威胁。','背甲卵圆形，盾片排列整齐，体色由橄榄绿至棕黑色；体重可达 200 公斤。','幼体在远洋漂流，成体回到近岸海草床觅食；雌性具有强烈的筑巢地忠诚性。','成体以海草与藻类为主，幼体偏杂食。',ARRAY['植食性', '杂食性']::text[],'热带与亚热带浅海海草床、珊瑚礁与沙滩。','雌龟每 2–4 年产卵一次，每窝 100 枚左右，孵化受沙温影响。',80,120,NULL,NULL,70,200,60,80,3,ARRAY['绿海龟的性别由孵化沙温决定，温度越高雌性比例越大。', '它们会回到出生海滩产卵，具有“ natal homing ”现象。', '海草床因绿海龟的持续取食而保持健康与更新。']::text[],'{"base":"#7E9471","deep":"#10201A","accent":"#C7B58A"}'::jsonb,'reptile',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='爬行纲 Reptilia' and order_name='龟鳖目 Testudines' and family='海龟科 Cheloniidae' and genus='Chelonia' limit 1),'EN'::conservation_status,'decreasing'::population_trend,2004,'IUCN 2004 年评估为濒危（全球）。区域种群差异显著，需参考最新区域评估。',ARRAY['渔具缠绕', '海岸开发', '塑料污染', '船只撞击', '偷猎与卵采集', '气候变化']::text[],ARRAY['海滩保护与照明管理', '渔具改良', '海洋保护区', '卫星追踪与社区巡护']::text[],ARRAY['全球热带与亚热带海域']::text[],ARRAY['众多沿海国家']::text[],ARRAY['海草床', '珊瑚礁', '沙滩']::text[],'全球性分布，但各区域种群需独立管理。',2442225,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Chelonia%20mydas','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='green-sea-turtle'),'fun_fact','趣闻 1','绿海龟的性别由孵化沙温决定，温度越高雌性比例越大。','IUCN Red List','https://www.iucnredlist.org/search?query=Chelonia%20mydas','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='green-sea-turtle'),'fun_fact','趣闻 2','它们会回到出生海滩产卵，具有“ natal homing ”现象。','IUCN Red List','https://www.iucnredlist.org/search?query=Chelonia%20mydas','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='green-sea-turtle'),'fun_fact','趣闻 3','海草床因绿海龟的持续取食而保持健康与更新。','IUCN Red List','https://www.iucnredlist.org/search?query=Chelonia%20mydas','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='green-sea-turtle'),'IUCN','EN'::conservation_status,'decreasing'::population_trend,2004,'IUCN 2004 年评估为濒危（全球）。区域种群差异显著，需参考最新区域评估。',ARRAY['渔具缠绕', '海岸开发', '塑料污染', '船只撞击', '偷猎与卵采集', '气候变化']::text[],ARRAY['海滩保护与照明管理', '渔具改良', '海洋保护区', '卫星追踪与社区巡护']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Chelonia%20mydas','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('african-penguin')::uuid,'african-penguin','非洲企鹅','African Penguin','Spheniscus demersus',ARRAY['斑嘴环企鹅', '公驴企鹅']::text[],'bird','鸟类','生活在温暖海岸的企鹅，叫声似驴鸣。','非洲企鹅是唯一繁殖于非洲南部的企鹅，分布于纳米比亚与南非海岸。它以黑白体色与胸前黑色斑点带著称。食物资源变化与航运活动导致其种群在 20 世纪后期以来显著下降。','体高 60–70 厘米，背部黑色、腹部白色，胸前有黑色斑点带，眼周有粉色裸皮。','群体繁殖，白天出海觅食，黄昏返回。叫声响亮，被昵称为“公驴企鹅”。','沙丁鱼、凤尾鱼、鲱鱼与鱿鱼。',ARRAY['肉食性']::text[],'非洲南部海岸与近岸岛屿，繁殖于沙质或岩石海岸。','通常每窝 2 枚卵，双亲共同孵育约 40 天。',60,70,60,70,2.2,3.5,10,15,20,ARRAY['每只非洲企鹅胸前的斑点图案独一无二。', '它们通过调节眼周粉红色腺体的血流来散热。', '非洲企鹅的叫声类似驴鸣，因此在南非被称为“公驴企鹅”。']::text[],'{"base":"#8FA3AD","deep":"#121B22","accent":"#D9A0A0"}'::jsonb,'bird',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='鸟纲 Aves' and order_name='企鹅目 Sphenisciformes' and family='企鹅科 Spheniscidae' and genus='Spheniscus' limit 1),'EN'::conservation_status,'decreasing'::population_trend,2024,'IUCN 评估为濒危（2024 年复核结果待最终核验）。南非与纳米比亚繁殖对数量在过去数十年大幅下降。',ARRAY['食物资源竞争', '航运与石油泄漏', '巢址干扰', '气候变化', '捕食者压力']::text[],ARRAY['渔业管理调整', '人工巢箱', '保护区与禁渔区', '种群监测与康复救助']::text[],ARRAY['非洲南部海岸']::text[],ARRAY['南非', '纳米比亚']::text[],ARRAY['海岸带', '近岸岛屿', '本格拉上升流区']::text[],'分布集中于南非与纳米比亚海岸及近岸岛屿。',5229384,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Spheniscus%20demersus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
