insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='african-penguin'),'fun_fact','趣闻 3','非洲企鹅的叫声类似驴鸣，因此在南非被称为“公驴企鹅”。','IUCN Red List','https://www.iucnredlist.org/search?query=Spheniscus%20demersus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
