insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('red-fox')::uuid,'red-fox','赤狐','Red Fox','Vulpes vulpes',ARRAY['红狐', '狐狸']::text[],'mammal','哺乳动物','分布最广的野生食肉目之一，适应城市与极地。','赤狐是犬科中分布范围最广的成员之一，从森林、草原到城市边缘都能生存。它以敏锐听觉与灵活行为著称，食性高度机会主义。人类活动既带来威胁，也为其扩张提供了通道。','体长 45–90 厘米，尾长约 30–55 厘米；毛色从赤褐到黑色不等，尾尖常为白色。','多为独居或成对活动，夜行性较强；具有固定的活动路线与气味标记行为。','小型哺乳动物、鸟类、昆虫、果实与人类食物残渣。',ARRAY['杂食性']::text[],'森林、草原、农田、城市边缘与苔原。','冬季繁殖，妊娠期约 52 天，每胎 4–6 仔。',45,90,35,50,3,14,3,6,50,ARRAY['赤狐能听到啮齿类在雪下活动的声音，并精准跃起捕食。', '它的地磁感知可能参与“朝北跳跃”捕猎策略的研究。', '城市赤狐的活动节律常比乡村个体更偏夜间。']::text[],'{"base":"#B9612F","deep":"#241109","accent":"#E0A46A"}'::jsonb,'canine',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='食肉目 Carnivora' and family='犬科 Canidae' and genus='Vulpes' limit 1),'LC'::conservation_status,'stable'::population_trend,2016,'IUCN 2016 年评估为无危。全球种群规模大且分布广泛，但局部地区受狂犬病与迫害影响。',ARRAY['栖息地改变', '道路死亡', '疾病', '局部迫害']::text[],ARRAY['野生动物疫病监测', '城市共存管理', '栖息地连通性']::text[],ARRAY['欧亚大陆', '北美洲', '北非', '澳大利亚（引入）']::text[],ARRAY['众多国家']::text[],ARRAY['温带森林', '草原', '苔原', '城市']::text[],'自然分布覆盖北半球大部分地区；澳大利亚种群为引入种群。',5219243,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Vulpes%20vulpes','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='red-fox'),'fun_fact','趣闻 1','赤狐能听到啮齿类在雪下活动的声音，并精准跃起捕食。','IUCN Red List','https://www.iucnredlist.org/search?query=Vulpes%20vulpes','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='red-fox'),'fun_fact','趣闻 2','它的地磁感知可能参与“朝北跳跃”捕猎策略的研究。','IUCN Red List','https://www.iucnredlist.org/search?query=Vulpes%20vulpes','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='red-fox'),'fun_fact','趣闻 3','城市赤狐的活动节律常比乡村个体更偏夜间。','IUCN Red List','https://www.iucnredlist.org/search?query=Vulpes%20vulpes','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='red-fox'),'IUCN','LC'::conservation_status,'stable'::population_trend,2016,'IUCN 2016 年评估为无危。全球种群规模大且分布广泛，但局部地区受狂犬病与迫害影响。',ARRAY['栖息地改变', '道路死亡', '疾病', '局部迫害']::text[],ARRAY['野生动物疫病监测', '城市共存管理', '栖息地连通性']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Vulpes%20vulpes','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('mountain-gorilla')::uuid,'mountain-gorilla','山地大猩猩','Mountain Gorilla','Gorilla beringei beringei',ARRAY['大猩猩']::text[],'mammal','哺乳动物','在云雾森林中生活的温和巨猿，种群正在缓慢回升。','山地大猩猩分布于东非维龙加火山群与布温迪不可渗透森林，是东部大猩猩的亚种。它以植食为主，群体由银背雄性领导。长期保护使其种群在近几十年有所增长，但极危状态尚未解除。','成年雄性体重可达 200 公斤以上，背部银灰色毛被称为“银背”；鼻孔大，体毛浓密。','以家族群为单位活动，银背雄性负责决策与防卫。日间多在地面觅食，夜间筑巢休息。','以树叶、茎、竹笋、果实与昆虫为主。',ARRAY['植食性']::text[],'海拔 2,200–4,300 米的云雾森林与竹林。','妊娠期约 8.5 个月，通常每胎 1 仔，间隔 3–4 年。',130,180,140,170,70,220,35,40,NULL,ARRAY['银背并非独立物种，而是成年雄性背部毛发变色的结果。', '山地大猩猩会使用树枝等植物材料制作简易工具。', '它们的群体决策常由银背雄性主导，但雌性也会迁移群体。']::text[],'{"base":"#5D5B4F","deep":"#161A14","accent":"#8C8A72"}'::jsonb,'primate',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='灵长目 Primates' and family='人科 Hominidae' and genus='Gorilla' limit 1),'CR'::conservation_status,'increasing'::population_trend,2018,'IUCN 2018 年评估为极危。最新调查显示种群超过 1,000 只，呈缓慢增长，但数量仍低。',ARRAY['栖息地丧失', '人类活动干扰', '偷猎陷阱', '疾病传播', '气候变化']::text[],ARRAY['跨境保护合作', '生态旅游收益共享', '反盗猎巡护', '兽医干预与疾病监测']::text[],ARRAY['东非裂谷西部山地']::text[],ARRAY['卢旺达', '乌干达', '刚果民主共和国']::text[],ARRAY['山地云雾林', '竹林']::text[],'仅分布于维龙加火山群与布温迪森林两个隔离区域。',4267319,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Gorilla%20beringei%20beringei','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='mountain-gorilla'),'fun_fact','趣闻 1','银背并非独立物种，而是成年雄性背部毛发变色的结果。','IUCN Red List','https://www.iucnredlist.org/search?query=Gorilla%20beringei%20beringei','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
