insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='mountain-gorilla'),'fun_fact','趣闻 3','它们的群体决策常由银背雄性主导，但雌性也会迁移群体。','IUCN Red List','https://www.iucnredlist.org/search?query=Gorilla%20beringei%20beringei','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='mountain-gorilla'),'IUCN','CR'::conservation_status,'increasing'::population_trend,2018,'IUCN 2018 年评估为极危。最新调查显示种群超过 1,000 只，呈缓慢增长，但数量仍低。',ARRAY['栖息地丧失', '人类活动干扰', '偷猎陷阱', '疾病传播', '气候变化']::text[],ARRAY['跨境保护合作', '生态旅游收益共享', '反盗猎巡护', '兽医干预与疾病监测']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Gorilla%20beringei%20beringei','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('bornean-orangutan')::uuid,'bornean-orangutan','婆罗洲猩猩','Bornean Orangutan','Pongo pygmaeus',ARRAY['红毛猩猩', '猩猩']::text[],'mammal','哺乳动物','雨林树冠上的大型灵长类，正面临栖息地快速消失。','婆罗洲猩猩是亚洲唯一的大型类人猿之一，以红褐色毛发与长臂著称。它们高度依赖低地雨林，取食果实并传播种子。油棕扩张与森林火灾导致栖息地急剧缩减。','雄性体重可达 90 公斤，脸颊有脂肪垫；雌性体型较小。手臂展开可超过 2 米。','以树栖为主，雄性多独居，雌性与幼崽形成稳定关系。会用树叶制作雨伞与巢。','以果实为主，也取食树叶、树皮、花与昆虫。',ARRAY['杂食性']::text[],'婆罗洲低地热带雨林与泥炭沼泽森林。','妊娠期约 8.5 个月，每 6–8 年产 1 仔，是繁殖最慢的哺乳动物之一。',120,150,110,140,30,90,35,45,NULL,ARRAY['婆罗洲猩猩会用大叶片当作雨伞。', '它们每晚在树上搭建新的巢，睡眠姿势会影响巢的结构。', '雄性脸颊的脂肪垫与长喉囊有助于发出长叫声。']::text[],'{"base":"#A8663C","deep":"#22120A","accent":"#D69A6A"}'::jsonb,'primate',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='灵长目 Primates' and family='人科 Hominidae' and genus='Pongo' limit 1),'CR'::conservation_status,'decreasing'::population_trend,2016,'IUCN 2016 年评估为极危。种群数量估计存在较大不确定性，主要威胁为栖息地丧失。',ARRAY['油棕种植扩张', '森林火灾', '非法捕猎', '宠物贸易', '栖息地破碎化']::text[],ARRAY['森林保护区', '可持续棕榈油认证', '康复与放归', '社区保护协议']::text[],ARRAY['东南亚婆罗洲']::text[],ARRAY['印度尼西亚', '马来西亚']::text[],ARRAY['低地雨林', '泥炭沼泽森林']::text[],'分布于婆罗洲，具体亚种分布需按最新分类核对。',5219532,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Pongo%20pygmaeus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
