insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='bornean-orangutan'),'fun_fact','趣闻 3','雄性脸颊的脂肪垫与长喉囊有助于发出长叫声。','IUCN Red List','https://www.iucnredlist.org/search?query=Pongo%20pygmaeus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='bornean-orangutan'),'IUCN','CR'::conservation_status,'decreasing'::population_trend,2016,'IUCN 2016 年评估为极危。种群数量估计存在较大不确定性，主要威胁为栖息地丧失。',ARRAY['油棕种植扩张', '森林火灾', '非法捕猎', '宠物贸易', '栖息地破碎化']::text[],ARRAY['森林保护区', '可持续棕榈油认证', '康复与放归', '社区保护协议']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Pongo%20pygmaeus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('peregrine-falcon')::uuid,'peregrine-falcon','游隼','Peregrine Falcon','Falco peregrinus',ARRAY['隼']::text[],'bird','鸟类','俯冲速度最快的动物之一，也是城市天空的猎手。','游隼是全球分布最广的猛禽之一，以高速俯冲捕食鸟类著称。20 世纪因有机氯农药导致卵壳变薄而大幅衰退，禁用后种群显著恢复，并成功适应城市高楼繁殖。','体长 34–58 厘米，翼展可达 1.2 米；背部蓝灰色，头部有深色“头盔”纹，胸腹有横斑。','领域性强，常在水边或悬崖筑巢；城市个体利用高楼平台。捕猎时从高空俯冲。','以中型鸟类为主，如鸽、鸭、鸥与鸣禽。',ARRAY['肉食性']::text[],'悬崖、河谷、海岸与城市高楼。','每窝 2–4 枚卵，孵化约 32 天，育雏约 6 周。',34,58,NULL,NULL,0.33,1,12,15,389,ARRAY['游隼俯冲速度可超过 300 公里/小时，是已知最快的动物运动之一。', '它的鼻孔内有特殊骨质结构，帮助在高速气流中呼吸。', '城市中的游隼常选择高楼或桥梁作为替代悬崖。']::text[],'{"base":"#7C8994","deep":"#10161B","accent":"#C8B26A"}'::jsonb,'bird',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='鸟纲 Aves' and order_name='隼形目 Falconiformes' and family='隼科 Falconidae' and genus='Falco' limit 1),'LC'::conservation_status,'increasing'::population_trend,2015,'IUCN 2015 年评估为无危。全球种群在禁用有机氯农药后显著恢复，部分地区仍在监测。',ARRAY['农药污染', '栖息地干扰', '非法捕猎', '气候变化']::text[],ARRAY['农药管制', '巢箱与监测', '迁徙通道保护', '公众科学']::text[],ARRAY['全球（除极地部分区域）']::text[],ARRAY['众多国家']::text[],ARRAY['悬崖', '河谷', '海岸', '城市']::text[],'分布广泛，包含多个亚种，迁徙模式因地区而异。',2481047,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Falco%20peregrinus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='peregrine-falcon'),'fun_fact','趣闻 1','游隼俯冲速度可超过 300 公里/小时，是已知最快的动物运动之一。','IUCN Red List','https://www.iucnredlist.org/search?query=Falco%20peregrinus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='peregrine-falcon'),'fun_fact','趣闻 2','它的鼻孔内有特殊骨质结构，帮助在高速气流中呼吸。','IUCN Red List','https://www.iucnredlist.org/search?query=Falco%20peregrinus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='peregrine-falcon'),'fun_fact','趣闻 3','城市中的游隼常选择高楼或桥梁作为替代悬崖。','IUCN Red List','https://www.iucnredlist.org/search?query=Falco%20peregrinus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='peregrine-falcon'),'IUCN','LC'::conservation_status,'increasing'::population_trend,2015,'IUCN 2015 年评估为无危。全球种群在禁用有机氯农药后显著恢复，部分地区仍在监测。',ARRAY['农药污染', '栖息地干扰', '非法捕猎', '气候变化']::text[],ARRAY['农药管制', '巢箱与监测', '迁徙通道保护', '公众科学']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Falco%20peregrinus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('vaquita')::uuid,'vaquita','小头鼠海豚','Vaquita','Phocoena sinus',ARRAY['加湾鼠海豚']::text[],'mammal','哺乳动物','世界上最稀有的海洋哺乳动物，仅存于墨西哥湾北部。','小头鼠海豚是墨西哥加利福尼亚湾北部的特有物种，也是全球最濒危的海洋哺乳动物。它主要死于刺网缠绕。尽管保护区与禁网措施已实施，种群仍处于极低水平。','体长约 1.5 米，是体型最小的鲸豚类之一；眼周有深色斑块，背鳍较小。','多为独居或小群活动，行为隐蔽，难以观察。','小型鱼类、鱿鱼与甲壳类。',ARRAY['肉食性']::text[],'墨西哥加利福尼亚湾北部浅海，泥沙底质与强潮汐混合水域。','繁殖生物学资料有限，妊娠期估计约 10–11 个月。',130,150,NULL,NULL,30,55,20,25,NULL,ARRAY['小头鼠海豚是 20 世纪才被科学描述的鲸豚类。', '它的背鳍前缘有明显的凹口，眼周有深色“面罩”。', '种群数量极低，每一次死亡都显著影响物种存续概率。']::text[],'{"base":"#9AA6A1","deep":"#121B1E","accent":"#6E7F82"}'::jsonb,'whale',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='鲸偶蹄目 Cetartiodactyla' and family='鼠海豚科 Phocoenidae' and genus='Phocoena' limit 1),'CR'::conservation_status,'decreasing'::population_trend,2018,'IUCN 2018 年评估为极危。近年调查估计野外个体仅剩个位数至数十只，需以最新国际调查为准。',ARRAY['刺网缠绕（主要）', '非法渔业', '栖息地改变', '遗传多样性极低']::text[],ARRAY['刺网禁令', '替代渔具研发', '保护区巡逻', '国际合作与声学监测']::text[],ARRAY['墨西哥加利福尼亚湾北部']::text[],ARRAY['墨西哥']::text[],ARRAY['浅海', '河口混合水域']::text[],'分布范围极小，仅限加利福尼亚湾北部约 4,000 平方公里海域。',2440665,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Phocoena%20sinus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
