insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='vaquita'),'fun_fact','趣闻 3','种群数量极低，每一次死亡都显著影响物种存续概率。','IUCN Red List','https://www.iucnredlist.org/search?query=Phocoena%20sinus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='vaquita'),'IUCN','CR'::conservation_status,'decreasing'::population_trend,2018,'IUCN 2018 年评估为极危。近年调查估计野外个体仅剩个位数至数十只，需以最新国际调查为准。',ARRAY['刺网缠绕（主要）', '非法渔业', '栖息地改变', '遗传多样性极低']::text[],ARRAY['刺网禁令', '替代渔具研发', '保护区巡逻', '国际合作与声学监测']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Phocoena%20sinus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('amur-leopard')::uuid,'amur-leopard','远东豹','Amur Leopard','Panthera pardus orientalis',ARRAY['东北豹', '阿穆尔豹']::text[],'mammal','哺乳动物','在温带针阔混交林中独行的极危亚种。','远东豹分布于俄罗斯远东与中国东北交界地带，是分布最北的豹亚种。它适应严寒，冬季被毛长而浓密。种群数量极低但近年有所增长，栖息地碎片化与偷猎仍是主要风险。','体长 100–140 厘米，被毛较其他豹亚种更长；斑纹间距较大，冬季毛色偏浅。','独居，领域范围大，多在夜间活动。善攀爬与游泳，常沿山脊巡行。','狍、梅花鹿、野猪与小型哺乳动物。',ARRAY['肉食性']::text[],'温带针阔混交林与山地森林，冬季积雪深厚。','妊娠期约 90–105 天，每胎 1–4 仔。',100,140,60,75,25,70,10,15,56,ARRAY['远东豹是唯一适应雪地严寒的豹亚种。', '它们的斑纹间距较宽，适应针叶林中的光影环境。', '跨境保护合作是种群恢复的关键。']::text[],'{"base":"#C9B48A","deep":"#1C1A12","accent":"#8A6E45"}'::jsonb,'cat',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='食肉目 Carnivora' and family='猫科 Felidae' and genus='Panthera' limit 1),'CR'::conservation_status,'increasing'::population_trend,2015,'IUCN 2015 年评估为极危。近年监测显示野生个体约 100 只左右，需以最新调查为准。',ARRAY['偷猎', '栖息地丧失', '猎物减少', '道路建设', '犬瘟热等疾病']::text[],ARRAY['跨境保护区', '反盗猎巡护', '猎物恢复', '生态廊道规划']::text[],ARRAY['俄罗斯远东', '中国东北']::text[],ARRAY['俄罗斯', '中国']::text[],ARRAY['温带针阔混交林', '山地森林']::text[],'分布区跨越中俄边境，核心区域为俄罗斯“豹之地”国家公园与中国东北虎豹国家公园。',5219440,true,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Panthera%20pardus%20orientalis','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
