insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='amur-leopard'),'IUCN','CR'::conservation_status,'increasing'::population_trend,2015,'IUCN 2015 年评估为极危。近年监测显示野生个体约 100 只左右，需以最新调查为准。',ARRAY['偷猎', '栖息地丧失', '猎物减少', '道路建设', '犬瘟热等疾病']::text[],ARRAY['跨境保护区', '反盗猎巡护', '猎物恢复', '生态廊道规划']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Panthera%20pardus%20orientalis','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('kakapo')::uuid,'kakapo','鸮鹦鹉','Kakapo','Strigops habroptilus',ARRAY['夜鹦鹉']::text[],'bird','鸟类','不会飞、夜间活动、体重最大的鹦鹉。','鸮鹦鹉是新西兰特有的一种夜行性、不会飞的鹦鹉，也是唯一实行求偶场（lek）繁殖的鹦鹉。它因入侵哺乳动物捕食而几近灭绝，目前所有个体均被转移至无捕食者的岛屿并接受密集管理。','体长 58–64 厘米，体重可达 2–4 公斤；黄绿色苔藓状羽毛，面盘似猫头鹰，翅膀退化。','夜间活动，嗅觉灵敏，通过气味寻找食物；雄性在求偶场发出低频“boom”声。','以本土植物的叶片、根、果实、种子与树液为主。',ARRAY['植食性']::text[],'新西兰原生森林与灌木，现主要分布于管理的无捕食者岛屿。','繁殖受食物丰度驱动，雌鸟每隔数年才繁殖一次，每窝 1–4 枚卵。',58,64,NULL,NULL,2,4,40,60,NULL,ARRAY['鸮鹦鹉是唯一不会飞的鹦鹉，也是体重最大的鹦鹉。', '雄性会挖掘求偶坑并发出低频共鸣声吸引雌性。', '它散发出独特的气味，反而容易被捕食者发现。']::text[],'{"base":"#7E8A4F","deep":"#161A0E","accent":"#C7C06A"}'::jsonb,'bird',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='鸟纲 Aves' and order_name='鹦鹉目 Psittaciformes' and family='鸮鹦鹉科 Strigopidae' and genus='Strigops' limit 1),'CR'::conservation_status,'increasing'::population_trend,2018,'IUCN 2018 年评估为极危。全部已知个体均处于管理保护之下，数量约 200 余只，需以新西兰环保部数据为准。',ARRAY['入侵捕食者', '繁殖率低', '遗传多样性低', '疾病', '食物供应波动']::text[],ARRAY['无捕食者岛屿管理', '人工辅助繁殖', '个体健康监测', '遗传管理']::text[],ARRAY['新西兰']::text[],ARRAY['新西兰']::text[],ARRAY['原生森林', '灌木']::text[],'野外历史分布限于新西兰；现今所有个体分布于管理的近海岛屿。',NULL,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Strigops%20habroptilus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='kakapo'),'fun_fact','趣闻 1','鸮鹦鹉是唯一不会飞的鹦鹉，也是体重最大的鹦鹉。','IUCN Red List','https://www.iucnredlist.org/search?query=Strigops%20habroptilus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='kakapo'),'fun_fact','趣闻 2','雄性会挖掘求偶坑并发出低频共鸣声吸引雌性。','IUCN Red List','https://www.iucnredlist.org/search?query=Strigops%20habroptilus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='kakapo'),'fun_fact','趣闻 3','它散发出独特的气味，反而容易被捕食者发现。','IUCN Red List','https://www.iucnredlist.org/search?query=Strigops%20habroptilus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='kakapo'),'IUCN','CR'::conservation_status,'increasing'::population_trend,2018,'IUCN 2018 年评估为极危。全部已知个体均处于管理保护之下，数量约 200 余只，需以新西兰环保部数据为准。',ARRAY['入侵捕食者', '繁殖率低', '遗传多样性低', '疾病', '食物供应波动']::text[],ARRAY['无捕食者岛屿管理', '人工辅助繁殖', '个体健康监测', '遗传管理']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Strigops%20habroptilus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('saiga')::uuid,'saiga','赛加羚羊','Saiga Antelope','Saiga tatarica',ARRAY['高鼻羚羊']::text[],'mammal','哺乳动物','拥有奇特膨大鼻部的草原迁徙者，种群曾因疾病骤减。','赛加羚羊分布于中亚与俄罗斯的草原和半荒漠，以膨大而灵活的鼻部著称，可在尘土与极端温度中过滤空气。20 世纪因偷猎锐减，2015 年大规模疾病又造成种群崩溃，目前仍在恢复中。','体长 100–140 厘米，雄性具半透明琥珀色角；鼻部膨大呈驼峰状，鼻孔朝下。','群居，具有季节性迁徙习性；奔跑速度快，善在开阔草原逃避捕食者。','以草原草本植物与盐生植物为主。',ARRAY['植食性']::text[],'中亚草原、半荒漠与干旱草原。','冬季发情，妊娠期约 140 天，每胎 1–2 仔。',100,140,60,80,26,45,6,10,80,ARRAY['赛加羚羊的膨大鼻部可过滤尘土，并在寒冷空气中预热吸入的空气。', '2015 年哈萨克斯坦发生大规模细菌性出血性败血症，造成约 20 万只死亡。', '雄性角呈半透明琥珀色，是非法贸易的目标。']::text[],'{"base":"#C2B18A","deep":"#211B10","accent":"#8E7A4E"}'::jsonb,'antelope',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='偶蹄目 Artiodactyla' and family='牛科 Bovidae' and genus='Saiga' limit 1),'CR'::conservation_status,'increasing'::population_trend,2018,'IUCN 2018 年评估为极危。2015 年疾病事件后种群有所恢复，但数量波动大。',ARRAY['偷猎（角）', '疾病暴发', '迁徙路线阻断', '气候变化', '草原开发']::text[],ARRAY['反盗猎巡护', '跨境迁徙保护', '疾病监测', '保护区网络']::text[],ARRAY['中亚', '俄罗斯南部']::text[],ARRAY['哈萨克斯坦', '蒙古', '俄罗斯', '乌兹别克斯坦']::text[],ARRAY['草原', '半荒漠']::text[],'分布与迁徙路线跨国，具体种群需按区域管理单元评估。',2441067,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Saiga%20tatarica','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='saiga'),'fun_fact','趣闻 1','赛加羚羊的膨大鼻部可过滤尘土，并在寒冷空气中预热吸入的空气。','IUCN Red List','https://www.iucnredlist.org/search?query=Saiga%20tatarica','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='saiga'),'fun_fact','趣闻 2','2015 年哈萨克斯坦发生大规模细菌性出血性败血症，造成约 20 万只死亡。','IUCN Red List','https://www.iucnredlist.org/search?query=Saiga%20tatarica','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='saiga'),'fun_fact','趣闻 3','雄性角呈半透明琥珀色，是非法贸易的目标。','IUCN Red List','https://www.iucnredlist.org/search?query=Saiga%20tatarica','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='saiga'),'IUCN','CR'::conservation_status,'increasing'::population_trend,2018,'IUCN 2018 年评估为极危。2015 年疾病事件后种群有所恢复，但数量波动大。',ARRAY['偷猎（角）', '疾病暴发', '迁徙路线阻断', '气候变化', '草原开发']::text[],ARRAY['反盗猎巡护', '跨境迁徙保护', '疾病监测', '保护区网络']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Saiga%20tatarica','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('black-rhino')::uuid,'black-rhino','黑犀','Black Rhinoceros','Diceros bicornis',ARRAY['钩唇犀']::text[],'mammal','哺乳动物','以钩状上唇取食灌木的犀牛，种群在保护中缓慢恢复。','黑犀分布于非洲东部与南部，以钩状上唇卷取灌木叶片。20 世纪后半叶因犀角盗猎数量骤降超过 90%，近年通过密集保护在部分区域恢复，但整体仍极危。','体长 3–3.8 米，体重 800–1,400 公斤；双角，前角较长；上唇呈钩状。','多独居，领域性强，通过粪便与气味标记；晨昏活动。','以灌木、树叶、嫩枝为主，是典型的瀏食者。',ARRAY['植食性']::text[],'非洲稀树草原、灌丛与干旱林地。','妊娠期约 15–16 个月，每 2.5–3 年产 1 仔。',300,380,140,180,800,1400,35,50,55,ARRAY['黑犀的名字并非来自体色，而是为了区别于“白犀”。', '它的上唇呈钩状，适合卷取灌木枝叶。', '黑犀视力较弱，但嗅觉与听觉敏锐。']::text[],'{"base":"#8B8178","deep":"#1A1714","accent":"#5E554D"}'::jsonb,'antelope',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='哺乳纲 Mammalia' and order_name='奇蹄目 Perissodactyla' and family='犀科 Rhinocerotidae' and genus='Diceros' limit 1),'CR'::conservation_status,'increasing'::population_trend,2011,'IUCN 2011 年评估为极危。区域种群趋势不一，整体数量仍远低于历史水平。',ARRAY['犀角盗猎', '栖息地丧失', '人兽冲突', '局部疾病']::text[],ARRAY['反盗猎武装巡护', '犀角去角手术', '保护区网络', '跨境执法合作']::text[],ARRAY['东非', '南部非洲']::text[],ARRAY['南非', '纳米比亚', '肯尼亚', '坦桑尼亚', '津巴布韦']::text[],ARRAY['稀树草原', '灌丛', '干旱林地']::text[],'分布碎片化，多个区域种群依赖持续保护。',5220111,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Diceros%20bicornis','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
