insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='black-rhino'),'IUCN','CR'::conservation_status,'increasing'::population_trend,2011,'IUCN 2011 年评估为极危。区域种群趋势不一，整体数量仍远低于历史水平。',ARRAY['犀角盗猎', '栖息地丧失', '人兽冲突', '局部疾病']::text[],ARRAY['反盗猎武装巡护', '犀角去角手术', '保护区网络', '跨境执法合作']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Diceros%20bicornis','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('bald-eagle')::uuid,'bald-eagle','白头海雕','Bald Eagle','Haliaeetus leucocephalus',ARRAY['白头鹰', '美洲雕']::text[],'bird','鸟类','北美天空的象征，从农药危机中恢复的猛禽。','白头海雕是北美的顶级猛禽，以白色头部与尾部著称（成鸟）。20 世纪因 DDT 导致繁殖失败而濒危，禁用后种群大幅恢复。它常在水体附近活动，以鱼类和水鸟为食。','翼展可达 2.2 米，成鸟头部与尾部白色，体羽深褐；喙与爪黄色。','领域性强，会重复使用巢址多年；常在水面上空盘旋或从栖枝俯冲捕鱼。','鱼类为主，也捕食水鸟、哺乳动物与腐肉。',ARRAY['肉食性']::text[],'北美海岸、湖泊、河流与湿地。','每窝 1–3 枚卵，孵化约 35 天，育雏期约 10–12 周。',70,100,NULL,NULL,3,6.3,20,30,48,ARRAY['白头海雕的白色头羽约在 4–5 岁性成熟时才完全长出。', '它们的巢是北美鸟类中最大的巢之一，可重达数吨。', '白头海雕并非真正的“海雕”之外唯一代表，其分类仍在讨论中。']::text[],'{"base":"#7C6E5C","deep":"#141210","accent":"#E8E4D8"}'::jsonb,'bird',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='鸟纲 Aves' and order_name='鹰形目 Accipitriformes' and family='鹰科 Accipitridae' and genus='Haliaeetus' limit 1),'LC'::conservation_status,'increasing'::population_trend,2016,'IUCN 2016 年评估为无危。北美种群在 DDT 禁用后显著恢复。',ARRAY['栖息地干扰', '铅弹中毒', '渔具缠绕', '污染', '气候变化']::text[],ARRAY['农药管制', '巢址保护', '铅弹替代倡导', '长期监测']::text[],ARRAY['北美洲']::text[],ARRAY['美国', '加拿大', '墨西哥北部']::text[],ARRAY['海岸', '湖泊', '河流', '湿地']::text[],'繁殖地与越冬地跨越北美，部分北方个体有迁徙行为。',2480446,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Haliaeetus%20leucocephalus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='bald-eagle'),'fun_fact','趣闻 1','白头海雕的白色头羽约在 4–5 岁性成熟时才完全长出。','IUCN Red List','https://www.iucnredlist.org/search?query=Haliaeetus%20leucocephalus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='bald-eagle'),'fun_fact','趣闻 2','它们的巢是北美鸟类中最大的巢之一，可重达数吨。','IUCN Red List','https://www.iucnredlist.org/search?query=Haliaeetus%20leucocephalus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='bald-eagle'),'fun_fact','趣闻 3','白头海雕并非真正的“海雕”之外唯一代表，其分类仍在讨论中。','IUCN Red List','https://www.iucnredlist.org/search?query=Haliaeetus%20leucocephalus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
insert into conservation_assessments (species_id,authority,status,trend,assessment_year,population_note,threats,measures,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='bald-eagle'),'IUCN','LC'::conservation_status,'increasing'::population_trend,2016,'IUCN 2016 年评估为无危。北美种群在 DDT 禁用后显著恢复。',ARRAY['栖息地干扰', '铅弹中毒', '渔具缠绕', '污染', '气候变化']::text[],ARRAY['农药管制', '巢址保护', '铅弹替代倡导', '长期监测']::text[],'IUCN Red List','https://www.iucnredlist.org/search?query=Haliaeetus%20leucocephalus','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial'::review_status);
insert into species (id,slug,name_cn,name_en,scientific_name,aliases,group_key,group_label,tagline,summary,appearance,behavior,diet,diet_type,habitat,reproduction,size_length_min_cm,size_length_max_cm,size_height_min_cm,size_height_max_cm,weight_min_kg,weight_max_kg,lifespan_min_years,lifespan_max_years,speed_kmh,fun_facts,palette,artwork,taxonomy_id,conservation_status,conservation_trend,assessment_year,population_note,threats,measures,distribution_regions,distribution_countries,distribution_biomes,distribution_note,gbif_taxon_key,featured,data_status,review_status,verified,source_name,source_url,license,retrieved_at,updated_at) values (md5('mandarin-duck')::uuid,'mandarin-duck','鸳鸯','Mandarin Duck','Aix galericulata',ARRAY['中国官鸭']::text[],'bird','鸟类','东亚湿地的华丽水鸟，雌雄羽色差异极大。','鸳鸯是东亚特有的树栖鸭类，繁殖于中国东北、俄罗斯远东、朝鲜半岛与日本，冬季南迁。雄性繁殖羽极为华丽，雌性偏灰褐。它们依赖成熟森林与湿地，也会利用城市公园水体。','雄性体长约 41–49 厘米，具橙红色帆状三级飞羽、白色眉纹与红色喙；雌性灰褐色，眼周有白色环。','多在树洞中筑巢，雏鸟孵化后跳跃入水；非繁殖期集群活动。','水生植物种子、果实、昆虫、软体动物与小鱼。',ARRAY['杂食性']::text[],'温带森林中的河流、湖泊、沼泽与公园水体。','每窝 9–12 枚卵，孵化约 28–30 天。',41,49,NULL,NULL,0.4,0.7,6,10,50,ARRAY['鸳鸯并非总是“一夫一妻终身”，配对关系通常维持一个繁殖季。', '雄性最醒目的橙色“帆羽”实为三级飞羽。', '雏鸟出生后从树洞跳下，落在水面或松软地面。']::text[],'{"base":"#B7784A","deep":"#1D1410","accent":"#D9C36A"}'::jsonb,'bird',(select id from taxonomies where kingdom='动物界 Animalia' and phylum='脊索动物门 Chordata' and class_name='鸟纲 Aves' and order_name='雁形目 Anseriformes' and family='鸭科 Anatidae' and genus='Aix' limit 1),'LC'::conservation_status,'decreasing'::population_trend,2016,'IUCN 2016 年评估为无危。全球种群规模需进一步核实，部分区域呈下降趋势。',ARRAY['森林采伐', '湿地排水', '狩猎', '城市化', '杂交与基因污染']::text[],ARRAY['湿地保护', '巢箱设置', '狩猎管理', '栖息地恢复']::text[],ARRAY['东亚']::text[],ARRAY['中国', '俄罗斯', '朝鲜半岛', '日本']::text[],ARRAY['温带森林湿地', '河流', '湖泊']::text[],'繁殖于东亚北部，冬季迁至中国南方与日本；欧洲有引入种群。',2498388,false,'curated'::data_status,'editorial'::review_status,false,'IUCN Red List','https://www.iucnredlist.org/search?query=Aix%20galericulata','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z','2026-11-01T00:00:00.000Z') on conflict (slug) do update set name_cn=excluded.name_cn,summary=excluded.summary,updated_at=now();
