insert into species_facts (species_id,kind,label,value,source_name,source_url,license,retrieved_at,verified,review_status) values ((select id from species where slug='mandarin-duck'),'fun_fact','趣闻 3','雏鸟出生后从树洞跳下，落在水面或松软地面。','IUCN Red List','https://www.iucnredlist.org/search?query=Aix%20galericulata','CC BY-NC-SA 3.0（站点内容引用；评估数据使用需遵守 IUCN 条款）','2026-11-01T00:00:00.000Z',false,'editorial');
