insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('mongabay-ZXJ2YXRpb24v','in-india-volunteers-map-riverside-trees-to-make-a-case-for-u-Rpb24v','In India, volunteers map riverside trees to make a case for urban conservation','印度浦那志愿者绘制河岸树木地图，为城市保护提供证据','Every weekend, several residents of Pune in India set out to map trees along the city’s riverbanks. It’s not just a weekend hobby; it’s meant to serve as evidence to protect the city’s greenery when developmental projects come up in the area, reports contributor Stephin Thomas for Mongabay. The volunteers are from Pune River Revival, […]','浦那居民每个周末沿河岸记录树木，希望在城市开发项目启动时，以系统化的树木地图作为保护城市绿地的依据。这项工作把公民参与转化为可引用的规划证据。','manual',ARRAY['城市生态', '公民科学', '树木地图', '印度']::text[],'conservation'::news_category,'Mongabay','mongabay','https://news.mongabay.com/feed/','https://news.mongabay.com/short-article/2026/11/in-india-volunteers-map-riverside-trees-to-make-a-case-for-urban-conservation/',NULL,'en','2026-11-13T08:22:04.000Z','2026-11-13T10:34:35.696Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。 中文标题与摘要由馆方编辑依据 RSS 摘要翻译整理，未逐句核对原文；原文标题、链接与发布日期保持不变。','editorial'::review_status,false,false,true) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('mongabay-MtYm9yZGVyLw','can-an-ancient-european-forest-be-saved-while-securing-polan-ZGVyLw','Can an ancient European forest be saved while securing Poland’s border?','保护古老森林与守卫波兰边境，能否同时做到？','Straddling the border between Poland and Belarus, the ancient Białowieża Forest, one of Europe’s last remaining primeval woodlands, is already under stress from decades of drainage, drought and habitat fragmentation. As geopolitical tensions and security threats from Russia and Belarus rise, Poland plans to construct a massive network of military fortifications along its 700-kilometer (435-mile) […]','横跨波兰与白俄罗斯边界的比亚沃维耶扎森林是欧洲仅存的原始林地之一，长期受到排水、干旱与栖息地破碎化压力。边境安全工程可能进一步影响这片森林，保护与安全之间的取舍引发关注。','manual',ARRAY['比亚沃维耶扎森林', '栖息地破碎化', '边境工程']::text[],'environment'::news_category,'Mongabay','mongabay','https://news.mongabay.com/feed/','https://news.mongabay.com/short-article/2026/11/can-an-ancient-european-forest-be-saved-while-securing-polands-border/',NULL,'en','2026-11-13T04:23:30.000Z','2026-11-13T10:34:35.696Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。 中文标题与摘要由馆方编辑依据 RSS 摘要翻译整理，未逐句核对原文；原文标题、链接与发布日期保持不变。','editorial'::review_status,false,false,true) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-jaWVzLmh0bWw','black-rhinos-are-mostly-loners-but-not-always-why-this-matte-mh0bWw','Black rhinos are mostly loners, but not always: Why this matters for saving the species','黑犀并非总是独行：社会行为研究对保护意味着什么','Black rhinos are notoriously aggressive, not just to humans but also to their fellow black rhinos. Aggression is so prevalent that injuries sustained after fighting with another black rhino are a common cause of death. Because of this aggression and their solitary nature, black rhino social behavior has been largely unexplored. Yet it may be key to conservation of this critically endangered African icon.','黑犀以攻击性强和独居著称，同类争斗造成的伤害甚至是常见死因。新的观察显示它们的社会行为比想象中复杂，这一认识可能影响保护区管理与种群恢复策略。','manual',ARRAY['黑犀', '社会行为', '保护管理']::text[],'conservation'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-black-rhinos-loners-species.html',NULL,'en','2026-11-13T01:30:01.000Z','2026-11-13T10:34:42.416Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。 中文标题与摘要由馆方编辑依据 RSS 摘要翻译整理，未逐句核对原文；原文标题、链接与发布日期保持不变。','editorial'::review_status,false,false,true) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-ybWFuLmh0bWw','not-afraid-of-ghosts-curiosity-and-fearlessness-apparent-in--mh0bWw','Not afraid of ghosts: Curiosity and fearlessness apparent in German shepherd genes','德国牧羊犬的基因差异：工作犬更好奇，展示犬更易焦虑','German shepherd dogs bred for working are more curious and less neurotic than German shepherds bred for show. A new study from Uppsala University and the Swedish University of Agricultural Sciences has shown that the differences are not only apparent in the dogs'' behavior, but also in their genes. In previous studies, similar genes in humans have been associated with neuroticism. The research is published in the jour','乌普萨拉大学与瑞典农业科学大学的研究发现，为工作培育的德国牧羊犬比展示犬更好奇、神经质程度更低，这些行为差异也能在基因层面观察到。','manual',ARRAY['德国牧羊犬', '行为遗传学', '驯化']::text[],'research'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-ghosts-curiosity-fearlessness-apparent-german.html',NULL,'en','2026-11-13T00:00:06.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。 中文标题与摘要由馆方编辑依据 RSS 摘要翻译整理，未逐句核对原文；原文标题、链接与发布日期保持不变。','editorial'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-cmlhbC5odG1s','parrots-vibrant-feathers-are-surprisingly-susceptible-to-bac-5odG1s','Parrots'' vibrant feathers are surprisingly susceptible to bacterial attack','艳丽羽毛的代价：鹦鹉羽色可能更易受细菌侵蚀','Flashy birds, from peacocks to parrots, have inspired a long tradition of using animal colors to study evolution. Colorful plumage often functions as a signal—for example, to attract a mate. Alternatively, drab colors can be used for camouflage. However, color can have functions beyond signaling and camouflage. This is because pigments, the molecules embedded in feather tissues to produce a broad range of colors, can','从孔雀到鹦鹉，鲜艳羽色长期被用于研究性选择与进化。新研究提示，色彩除了传递信号，还可能与羽毛对细菌攻击的易感性相关，显示色彩演化存在权衡。','manual',ARRAY['羽毛', '细菌', '性选择', '鹦鹉']::text[],'research'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-parrots-vibrant-feathers-susceptible-bacterial.html',NULL,'en','2026-11-12T23:40:05.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。 中文标题与摘要由馆方编辑依据 RSS 摘要翻译整理，未逐句核对原文；原文标题、链接与发布日期保持不变。','editorial'::review_status,false,false,true) on conflict (id) do nothing;
