insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-aW5jdC5odG1s','europe-s-look-alike-alpine-newts-turn-out-to-be-five-distinc-5odG1s','Europe''s look-alike Alpine newts turn out to be five distinct species','欧洲“同款”高山蝾螈其实是五个独立物种','What scientists until recently called the Alpine newt has turned out to be five different species, following genetic research by Leiden biologists. One of these species was even new to science and has now been given a name: Mesotriton similis.','莱顿大学的遗传研究发现，此前被归为同一种的高山蝾螈实际包含五个物种，其中一个为新种，命名为 Mesotriton similis。这提醒分类修订会直接影响保护单元的划分。','manual',ARRAY['高山蝾螈', '隐存种', '分类修订', '遗传研究']::text[],'new_species'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-europe-alike-alpine-newts-distinct.html',NULL,'en','2026-11-12T22:40:01.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。 中文标题与摘要由馆方编辑依据 RSS 摘要翻译整理，未逐句核对原文；原文标题、链接与发布日期保持不变。','editorial'::review_status,false,false,true) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-ZW5lcy5odG1s','new-ai-tool-exposes-plant-pathogens-and-the-genes-behind-the-5odG1s','New AI tool exposes plant pathogens and the genes behind them',NULL,'Can a bacterium''s DNA reveal whether it will make a plant sick? Bioinformatician Guillermo Guerrero Egido believes so. In his PhD research, he developed a computational method that not only identifies potential pathogens, but also the genes that may be responsible for their disease-causing abilities.',NULL,'pending_ai','{}'::text[],'research'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-ai-tool-exposes-pathogens-genes.html',NULL,'en','2026-11-12T22:00:11.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-ZGVlcC5odG1s','genetic-data-reveal-hidden-extinction-risks-in-the-deep-sea-5odG1s','Genetic data reveal hidden extinction risks in the deep sea','深海并非避难所：遗传数据揭示隐藏的灭绝风险','A biodiversity crisis is unfolding across the planet, but the deep sea was thought immune and even a refuge for marine life. New research led by Florida International University scientists and published in Nature Communications suggests that assumption may be alarmingly wrong.','以往观点认为深海生物受人类影响较小，甚至可充当海洋生命的避难所。佛罗里达国际大学团队发表于 Nature Communications 的研究认为，这一假设可能严重低估了深海生物多样性的风险。','manual',ARRAY['深海', '灭绝风险', '遗传多样性', '海洋保护']::text[],'conservation'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-genetic-reveal-hidden-extinction-deep.html',NULL,'en','2026-11-12T21:30:01.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。 中文标题与摘要由馆方编辑依据 RSS 摘要翻译整理，未逐句核对原文；原文标题、链接与发布日期保持不变。','editorial'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('mongabay-aWFsLXNpZGUv','in-brazil-s-prey-rich-pantanal-jaguars-reveal-a-surprisingly-NpZGUv','In Brazil’s prey-rich Pantanal, jaguars reveal a surprisingly social side','猎物丰富的潘塔纳尔湿地：美洲豹展现出意外的社会性','Jaguars are widely believed to be solitary cats, only tolerating others when mating or raising cubs. However, a new study in the Brazilian Pantanal has found the jaguars there often pair up and are far more social than expected. The Pantanal, the world’s largest wetland, has the world’s highest population density of jaguars (Panthera onca), […]','美洲豹通常被视为独居猫科动物，只在交配或育幼时容忍同类。巴西潘塔纳尔湿地的新研究发现，当地美洲豹常成对活动，社会性远超预期；该湿地拥有全球最高的美洲豹密度。','manual',ARRAY['美洲豹', '潘塔纳尔', '社会行为', '猫科']::text[],'research'::news_category,'Mongabay','mongabay','https://news.mongabay.com/feed/','https://news.mongabay.com/short-article/2026/11/in-brazils-prey-rich-pantanal-jaguars-reveal-a-surprisingly-social-side/',NULL,'en','2026-11-12T20:45:40.000Z','2026-11-13T10:34:35.696Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。 中文标题与摘要由馆方编辑依据 RSS 摘要翻译整理，未逐句核对原文；原文标题、链接与发布日期保持不变。','editorial'::review_status,false,false,true) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-13ZWIuaHRtbA','how-a-warming-ocean-is-changing-the-base-of-the-marine-food--aHRtbA','How a warming ocean is changing the base of the marine food web','变暖的海洋正在改变海洋食物网的基底','Climate change is causing warming in the oceans, which can have significant effects on marine food webs. Rising ocean temperatures can intensify seawater stratification, a process in which ocean water forms layers of different densities that mix less readily. This can reduce the supply of nutrients to surface waters and favor smaller phytoplankton species that are better adapted to low-nutrient conditions. Phytoplank','海洋升温会加剧海水层化，使不同密度的水层更难混合，进而影响营养盐供应与浮游生物生产。研究关注这种变化如何从食物网基底向上传导。','manual',ARRAY['海洋变暖', '层化', '浮游生物', '食物网']::text[],'environment'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-ocean-base-marine-food-web.html',NULL,'en','2026-11-12T20:10:01.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。 中文标题与摘要由馆方编辑依据 RSS 摘要翻译整理，未逐句核对原文；原文标题、链接与发布日期保持不变。','editorial'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('mongabay-1maXNoaW5nLw','us-renews-push-to-open-pacific-marine-protected-area-to-fish-aW5nLw','US renews push to open Pacific marine protected area to fishing','美国再次推动在太平洋海洋保护区内开放商业捕鱼','The U.S. government has published proposed rules to allow commercial fishing in an area more than double the size of California inside a Pacific marine reserve that encompasses a network of islands, atolls, seamounts and coral reef systems. The proposed rules, published Nov. 9 by the National Oceanic and Atmospheric Administration’s National Marine Fisheries Service […]','美国政府公布拟议规则，计划在覆盖岛屿、环礁、海山与珊瑚礁系统的太平洋海洋保护区内开放商业捕鱼，涉及面积超过加利福尼亚州的两倍。规则由 NOAA 于 11 月 9 日发布。','manual',ARRAY['海洋保护区', '商业捕鱼', 'NOAA', '珊瑚礁']::text[],'conservation'::news_category,'Mongabay','mongabay','https://news.mongabay.com/feed/','https://news.mongabay.com/short-article/2026/11/us-renews-push-to-open-pacific-marine-protected-area-to-fishing/',NULL,'en','2026-11-12T20:06:26.000Z','2026-11-13T10:34:35.696Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。 中文标题与摘要由馆方编辑依据 RSS 摘要翻译整理，未逐句核对原文；原文标题、链接与发布日期保持不变。','editorial'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-sZW50Lmh0bWw','scientists-uncover-how-limestone-eating-shipworms-breed-in-t-mh0bWw','Scientists uncover how limestone-eating shipworms breed in turbulent water',NULL,'Researchers from Northeastern University''s Ocean Genome Legacy Center (OGL) have taken the next step toward deciphering the life cycle and unusual reproductive strategies of a limestone-eating species of shipworm. The results could ultimately usher in new developments in lifesaving medicine.',NULL,'pending_ai','{}'::text[],'environment'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-scientists-uncover-limestone-shipworms-turbulent.html',NULL,'en','2026-11-12T20:00:01.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-ZWRnZS5odG1s','same-fertilizer-different-timing-nutrient-pulses-give-two-in-5odG1s','Same fertilizer, different timing: Nutrient pulses give two invasive plants an edge',NULL,'Fluctuating resource supplies can help some highly invasive plants outcompete native species. But research on how nutrient fluctuations affect plant invasion has largely relied on greenhouse or simplified experiments, leaving it unclear whether the same mechanisms operate under natural conditions.',NULL,'pending_ai','{}'::text[],'research'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-fertilizer-nutrient-pulses-invasive-edge.html',NULL,'en','2026-11-12T19:50:01.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-0aW9uLmh0bWw','talking-or-just-meowing-food-test-suggests-cats-call-for-hum-mh0bWw','Talking or just meowing? Food test suggests cats call for human attention',NULL,'As any cat owner knows, their feline companion is the boss of the home, and their meows are one way to get attention. But are those noises actually an attempt to communicate with us, or simply an expression of how the cat feels?',NULL,'pending_ai','{}'::text[],'research'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-meowing-food-cats-human-attention.html',NULL,'en','2026-11-12T19:40:20.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-9ya3MuaHRtbA','elephants-found-to-be-increasingly-isolated-leading-to-fract-aHRtbA','Elephants found to be increasingly isolated, leading to fractured social networks',NULL,'Humans and many other social animals thrive in well-established community networks. Asian elephants are one example of a species that flourishes in groups that work together to access food and care for their young, among other social bonds.',NULL,'pending_ai','{}'::text[],'research'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-elephants-isolated-fractured-social-networks.html',NULL,'en','2026-11-12T19:00:35.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-VybnMuaHRtbA','ant-colonies-defy-aging-patterns-as-death-risk-falls-and-rep-aHRtbA','Ant colonies defy aging patterns as death risk falls and reproduction rises',NULL,'Getting older usually brings a higher risk of death and declining reproduction. Yet for western harvester ant colonies, the opposite occurs. As a colony gets older, it becomes less likely to die and more likely to reproduce.',NULL,'pending_ai','{}'::text[],'research'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-ant-colonies-defy-aging-patterns.html',NULL,'en','2026-11-12T15:00:49.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
