insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-cmxpbi5odG1s','city-life-leaves-subtle-genetic-traces-in-berlin-squirrels-5odG1s','City life leaves subtle genetic traces in Berlin squirrels',NULL,'Roads, buildings and other infrastructure can restrict the movements of wildlife in cities. As a result, urban wildlife from different areas encounter one another less frequently, potentially resulting in reduced genetic diversity.',NULL,'pending_ai','{}'::text[],'research'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-city-life-subtle-genetic-berlin.html',NULL,'en','2026-11-12T13:40:07.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-JtZXIuaHRtbA','forests-in-japan-shift-toward-trees-adapted-to-warmer-climat-aHRtbA','Forests in Japan shift toward trees adapted to warmer climates',NULL,'Climate change has caused substantial alterations in forest ecosystems worldwide through changes in temperature and precipitation patterns. A new study from Osaka Metropolitan University (OMU) suggests that these effects are also evident in Japan, where forests are undergoing changes in structure and shifts toward tree types adapted to warmer climates.',NULL,'pending_ai','{}'::text[],'environment'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-forests-japan-shift-trees-warmer.html',NULL,'en','2026-11-12T12:20:01.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-wNTg1MC5odG0','crows-can-make-decisions-twice-as-fast-as-humans-scientists--C5odG0','Crows can make decisions twice as fast as humans, scientists discover',NULL,'Crows may be even smarter than we thought, and their brains are astonishingly fast. Researchers at the University of Tübingen discovered that crows can make visual decisions twice as quickly as humans and monkeys, taking just 235 milliseconds on average to identify the direction of moving dots while maintaining remarkable accuracy.',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261111005850.htm',NULL,'en','2026-11-12T12:17:19.000Z','2026-11-13T10:34:40.951Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-yNTUyOS5odG0','a-new-treasure-map-reveals-where-earth-s-lost-prehistoric-li-S5odG0','A new treasure map reveals where Earth''s lost prehistoric life may be hiding',NULL,'A sweeping analysis of 540 million years of marine fossils has revealed surprising gaps in our understanding of Earth''s ancient life. Scientists discovered that some of the greatest opportunities for finding previously unknown species lie in relatively recent geological periods, rather than the distant past. By mapping unexplored fossil-rich regions around the world, researchers have created a powerful tool to guide ',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261112025529.htm',NULL,'en','2026-11-12T11:24:47.000Z','2026-11-13T10:34:40.951Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-0MjU1Ni5odG0','a-butterfly-that-fooled-scientists-for-200-years-finally-rev-i5odG0','A butterfly that fooled scientists for 200 years finally reveals its secrets',NULL,'Researchers have discovered that a familiar tropical butterfly actually belongs to three nearly identical species, including one previously unknown to science. Hidden ultraviolet wing patterns and DNA differences revealed the truth, leaving scientists puzzled about how the butterflies remain genetically separate despite living side by side.',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261110042556.htm',NULL,'en','2026-11-12T10:47:43.000Z','2026-11-13T10:34:40.951Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
