insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-zMzEwMS5odG0','scientists-discover-that-necks-didn-t-evolve-for-the-reason--S5odG0','Scientists discover that necks didn''t evolve for the reason we thought',NULL,'Scientists have discovered that the first animals to venture onto land nearly 380 million years ago had surprisingly stiff necks, overturning a long-standing theory about evolution. Rather than evolving to help animals turn their heads, necks may have emerged as part of the anatomical changes that allowed them to move using their front limbs.',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261108233101.htm',NULL,'en','2026-11-11T23:49:03.000Z','2026-11-13T10:34:40.951Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
