insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-b3JsZC5odG1s','scientists-find-some-of-the-very-last-wild-and-healthy-ecosy-5odG1s','Scientists find some of the ''very last wild and healthy ecosystems'' in the world''s oceans untouched by humans',NULL,'Humans have left their mark on virtually every place on the planet, from the deep sea to the peaks of the highest mountains. But a few very remote atolls in the Pacific Ocean may be exceptions. A new Frontiers in Marine Science study has found two coral atolls, Bikar and Bokak, located on the territory of the Marshall Islands, to be some of the most intact ecosystems remaining in the region and perhaps the world.',NULL,'pending_ai','{}'::text[],'environment'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-scientists-wild-healthy-ecosystems-world.html',NULL,'en','2026-11-11T22:00:08.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
