insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-VhbHMuaHRtbA','monkey-foot-and-palm-prints-differ-between-individuals-as-th-aHRtbA','Monkey foot and palm prints differ between individuals, as they do in humans',NULL,'In three species of monkey, the complex pattern of ridges on the feet and palms varies between individuals, similar to human fingerprints, according to a study published in the open-access journal PLOS One by Juliana Vieira Flores Sales at Universidade de Brasília and colleagues.',NULL,'pending_ai','{}'::text[],'research'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-monkey-foot-palm-differ-individuals.html',NULL,'en','2026-11-11T19:00:26.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-yZW1lLmh0bWw','a-double-defense-protects-photosynthesis-from-extreme-heat-mh0bWw','A double defense protects photosynthesis from extreme heat',NULL,'Photosynthesis is fundamental to life on Earth, allowing plants and microalgae to convert sunlight and carbon dioxide into organic compounds. However, this essential process is highly vulnerable to heat. As global temperatures rise and heat waves become more frequent, declining photosynthetic efficiency threatens agricultural productivity and the large-scale cultivation of microalgae for biofuels and other valuable p',NULL,'pending_ai','{}'::text[],'conservation'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-defense-photosynthesis-extreme.html',NULL,'en','2026-11-11T18:00:07.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
