insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-wNTQxMy5odG0','the-mystery-of-how-hair-knows-where-to-grow-may-finally-be-s-y5odG0','The mystery of how hair knows where to grow may finally be solved',NULL,'Scientists have discovered that the intricate patterns of hair follicles on mammals may arise from a remarkably simple process involving cells following chemical signals. The findings challenge a long-standing theory and reveal how nature can create complex biological patterns without a detailed blueprint.',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261109205413.htm',NULL,'en','2026-11-11T12:48:30.000Z','2026-11-13T10:34:40.951Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('physorg-dmVyeS5odG1s','deeper-dives-are-linked-to-longer-surface-recovery-in-sea-li-5odG1s','Deeper dives are linked to longer surface recovery in sea lions',NULL,'Sea lions, marine mammals belonging to the eared seal family, have to dive to search for food and other resources. Between dives, however, they return to the surface to breathe and recover.',NULL,'pending_ai','{}'::text[],'research'::news_category,'Phys.org','physorg','https://phys.org/rss-feed/biology-news/plants-animals/','https://phys.org/news/2026-11-deeper-linked-longer-surface-recovery.html',NULL,'en','2026-11-11T11:00:01.000Z','2026-11-13T10:34:42.417Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
