insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-wNTQwOS5odG0','237-million-year-old-fossils-reveal-a-bizarre-armored-sea-am-S5odG0','237-million-year-old fossils reveal a bizarre armored sea amphibian',NULL,'A bizarre, heavily armored amphibian roamed the oceans 237 million years ago, despite the fact that modern amphibians cannot survive entirely in saltwater. Discovered in China, the giant salamander-sized creature may be the first known amphibian to have adapted to a fully marine existence.',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261109205409.htm',NULL,'en','2026-11-11T00:59:32.000Z','2026-11-13T10:34:40.951Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
