insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('nature-2LTAzNDk5LXc','earth-s-early-history-told-by-3-9-billion-year-old-rocks-fro-Dk5LXc','Earth’s early history told by 3.9-billion-year-old rocks from northern China',NULL,'Nature, Published online: 11 November 2026; doi:10.1038/d41586-026-03499-w Ancient rocks in northern China reveal that by 3.95 billion years ago, surface-altered oceanic crust had been buried rapidly to depths greater than 50 kilometres and partly melted. This crust was derived from a mantle reservoir that had been left behind when the crust separated from the early mantle as early as 4.3 billion years ago.',NULL,'pending_ai','{}'::text[],'environment'::news_category,'Nature','nature','https://www.nature.com/nature.rss','https://www.nature.com/articles/d41586-026-03499-w',NULL,'en','2026-11-11T00:00:00.000Z','2026-11-13T10:34:38.069Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-4NTIwMS5odG0','paleontologists-discover-one-in-a-million-fossil-with-450-mi-S5odG0','Paleontologists discover “one-in-a-million” fossil with 450-million-year-old soft tissue',NULL,'Scientists have discovered a remarkably preserved 450-million-year-old fossil containing soft tissues from an ancient starfish relative, revealing unexpected details about marine life more than 200 million years before dinosaurs existed. Found in a museum collection, the extraordinarily rare specimen offers new clues about how Earth''s earliest reef animals fed, survived, and evolved.',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261105085201.htm',NULL,'en','2026-11-10T12:16:08.000Z','2026-11-13T10:34:40.952Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-3NDUxOC5odG0','scientists-discover-a-surprising-link-between-acorns-and-lym-C5odG0','Scientists discover a surprising link between acorns and lyme disease',NULL,'After more than 35 years of research, scientists have uncovered surprising clues about what really drives Lyme disease risk. Contrary to longstanding assumptions, deer populations appear less important than mice, which can fuel a 40% increase in tick numbers the following year. Even acorn production can predict tick population surges two years in advance, while extreme temperatures may be far less deadly to ticks tha',NULL,'pending_ai','{}'::text[],'research'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261106174518.htm',NULL,'en','2026-11-09T10:59:35.000Z','2026-11-13T10:34:40.952Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-yNDU1OC5odG0','hidden-climate-superpower-why-some-ocean-snow-carries-six-ti-C5odG0','Hidden climate superpower: Why some ocean “snow” carries six times more carbon',NULL,'Scientists have discovered that the stickiness of underwater “marine snow” plays a surprisingly important role in how much carbon reaches the deep ocean. Gooier particles resist bacterial breakdown and can transport more than six times as much carbon to the depths, revealing an unexpected connection between ocean slime and Earth''s climate.',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261105224558.htm',NULL,'en','2026-11-09T01:14:33.000Z','2026-11-13T10:34:40.952Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-4NDAxOS5odG0','scientists-discover-stunning-new-amazon-fish-that-may-alread-S5odG0','Scientists discover stunning new Amazon fish that may already be endangered',NULL,'Researchers have discovered a stunning new species of tiny orange-patterned fish in the Brazilian Amazon, but its survival may already be at risk. Named Laimosemion laranja, the brilliantly colored killifish measures less than three centimeters long and was found in just three small forest pools. Its extremely limited habitat is threatened by mining, deforestation, pollution, and expanding development.',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261104084019.htm',NULL,'en','2026-11-08T23:56:14.000Z','2026-11-13T10:34:40.952Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-3NDUzNS5odG0','an-ancient-ocean-full-of-giant-predators-reveals-a-surprisin-S5odG0','An ancient ocean full of giant predators reveals a surprising twist in evolution',NULL,'A remarkable fossil discovery in Colombia is challenging how scientists understand major evolutionary changes in Earth''s history. Researchers uncovered an incredibly diverse ancient marine ecosystem where giant reptiles, sharks, and other creatures thrived as older evolutionary groups approached extinction and newer ones emerged. They call this previously unrecognized pattern a "Biotic Inflection," suggesting that ma',NULL,'pending_ai','{}'::text[],'conservation'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261106174535.htm',NULL,'en','2026-11-08T22:45:01.000Z','2026-11-13T10:34:40.952Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-3NDUyOC5odG0','ancient-siberian-tomb-reveals-surprising-secrets-of-cannabis-C5odG0','Ancient Siberian tomb reveals surprising secrets of cannabis use 2,800 years ago',NULL,'Scientists investigating a 2,800-year-old Siberian tomb discovered roughly 1,000 cannabis seeds and chemical evidence suggesting ancient Scythians used the plant for its intoxicating effects. The remarkable find, surrounded by evidence of elaborate burial rituals and animal sacrifices, offers the oldest directly dated archaeological evidence of psychoactive cannabis use.',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261106174528.htm',NULL,'en','2026-11-08T08:14:23.000Z','2026-11-13T10:34:40.952Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-yNDU0Mi5odG0','scientists-just-found-dinosaur-blood-that-survived-115-milli-i5odG0','Scientists just found dinosaur blood that survived 115 million years',NULL,'Scientists have discovered chemically confirmed traces of ancient blood inside 115-million-year-old dinosaur bones, challenging assumptions about how long biological molecules can survive. The extraordinary preservation could unlock new clues about dinosaur physiology and even help scientists search for ancient life elsewhere in the universe.',NULL,'pending_ai','{}'::text[],'new_species'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261105224542.htm',NULL,'en','2026-11-06T11:28:01.000Z','2026-11-13T10:34:40.952Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
insert into news_articles (id,slug,title_original,title_cn,excerpt_original,summary_cn,summary_status,keywords,category,source_name,source_id,source_url,original_url,image_url,language,published_at,retrieved_at,license_note,review_status,verified,ai_generated,featured) values ('sciencedaily-wMzIwMC5odG0','five-inch-long-beetle-larvae-are-quietly-destroying-blueberr-C5odG0','Five-inch-long beetle larvae are quietly destroying blueberry roots',NULL,'Scientists have solved a mystery surrounding destructive beetles attacking blueberry bushes in North Carolina, identifying a species whose massive larvae can grow up to five inches long and destroy plant roots. Although farmers have reported damage for more than a decade, the insects responsible remained unidentified until researchers used DNA analysis to uncover the culprit.',NULL,'pending_ai','{}'::text[],'incident'::news_category,'ScienceDaily','sciencedaily','https://www.sciencedaily.com/rss/plants_animals.xml','https://www.sciencedaily.com/releases/2026/11/261103003200.htm',NULL,'en','2026-11-06T09:33:36.000Z','2026-11-13T10:34:40.952Z','仅使用 RSS 标题、摘要与链接；未转载全文与图片。版权归原作者与出版机构。','pending_review'::review_status,false,false,false) on conflict (id) do nothing;
