insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-001','大熊猫的前掌上用来抓握竹子的“伪拇指”来自哪种结构？',ARRAY['额外生长的第六指', '腕部籽骨的延长', '特化的爪甲', '掌骨融合']::text[],1,'大熊猫的“伪拇指”是腕部籽骨（桡侧籽骨）的延长结构，并非真正的手指。这一结构帮助它在取食竹子时更稳定地抓握。',2,'解剖','Wikipedia · Giant panda','https://en.wikipedia.org/wiki/Giant_panda','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-002','以下哪种动物终生保留外鳃，并具有肢体再生能力？',ARRAY['墨西哥钝口螈', '绿海龟', '帝企鹅', '雪豹']::text[],0,'墨西哥钝口螈具有幼态延续现象，终生保留外鳃，并能再生四肢、尾巴与部分脊髓组织。',1,'两栖动物','San Diego Zoo Wildlife Alliance','https://animals.sandiegozoo.org/animals/axolotl','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-003','蓝鲸的主要食物是什么？',ARRAY['大型鱼类', '磷虾', '海草', '头足类']::text[],1,'蓝鲸是滤食性须鲸，几乎完全以磷虾为食，觅食季每天可摄入数吨磷虾。',1,'食性','NOAA Fisheries · Blue Whale','https://www.fisheries.noaa.gov/species/blue-whale','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-004','长颈鹿的颈部有多少节颈椎？',ARRAY['7 节', '12 节', '20 节', '数量因亚种而异']::text[],0,'长颈鹿与人类一样只有 7 节颈椎，但每节颈椎被极度延长。这是哺乳动物颈椎数量保守性的经典例子。',2,'解剖','Wikipedia · Giraffe','https://en.wikipedia.org/wiki/Giraffe','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-005','帝企鹅的孵卵任务主要由谁承担？',ARRAY['雌鸟', '雄鸟', '双亲轮流', '群体共同']::text[],1,'雌鸟产下单枚卵后会前往海中觅食，雄鸟将卵放在脚背上、以育儿袋覆盖，持续孵化约 65 天，期间几乎不进食。',1,'繁殖','British Antarctic Survey','https://www.bas.ac.uk/','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-006','非洲草原象的妊娠期约为多久？',ARRAY['约 3 个月', '约 9 个月', '约 15 个月', '约 22 个月']::text[],3,'非洲草原象妊娠期约 22 个月，是陆生哺乳动物中最长的妊娠期之一。',3,'繁殖','Animal Diversity Web','https://animaldiversity.org/accounts/Loxodonta_africana/','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-007','帝王蝶的北美迁徙种群依靠什么完成定向？',ARRAY['学习记忆', '地磁场与太阳方位', '群体跟随', '气味标记']::text[],1,'研究表明帝王蝶利用太阳方位与体内时钟，并可能感知地磁场，完成跨代迁徙。',2,'行为','US Fish & Wildlife Service','https://www.fws.gov/initiative/monarch-butterfly','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-008','以下哪种动物是唯一不会飞的鹦鹉？',ARRAY['鸮鹦鹉', '非洲灰鹦鹉', '金刚鹦鹉', '葵花凤头鹦鹉']::text[],0,'鸮鹦鹉是新西兰特有的夜行性鹦鹉，翅膀退化、不会飞行，也是体重最大的鹦鹉。',1,'鸟类','New Zealand Department of Conservation','https://www.doc.govt.nz/nature/native-animals/birds/birds-a-z/kakapo/','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-009','小头鼠海豚（Vaquita）面临的最主要直接威胁是什么？',ARRAY['船只撞击', '刺网缠绕', '海洋噪声', '塑料误食']::text[],1,'小头鼠海豚主要死于非法刺网渔业中的缠绕。保护措施的核心是替代渔具与刺网禁令。',2,'保护','NOAA Fisheries · Vaquita','https://www.fisheries.noaa.gov/species/vaquita','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-010','游隼俯冲时的速度可以达到什么量级？',ARRAY['约 80 km/h', '约 150 km/h', '超过 300 km/h', '约 500 km/h']::text[],2,'游隼在俯冲捕猎时可超过 300 km/h，是已知最快的动物运动之一。该数值为极端俯冲速度，并非巡航速度。',2,'运动','The Peregrine Fund','https://peregrinefund.org/','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-011','赛加羚羊膨大的鼻部有什么功能？',ARRAY['储存水分', '过滤尘土并调节吸入空气', '增强嗅觉定位', '发出低频叫声']::text[],1,'赛加羚羊的鼻部结构可在沙尘环境中过滤空气，并在寒冷季节预热吸入的空气。',2,'解剖','Saiga Conservation Alliance','https://saiga-conservation.org/','editorial') on conflict (id) do nothing;
insert into quiz_questions (id,question,options,answer_index,explanation,difficulty,category,source_name,source_url,review_status) values ('q-012','关于保护等级，以下哪种说法是严谨的？',ARRAY['“濒危”是一个永恒不变的标签', '保护等级应标注来源、评估年份与适用范围', '所有动物的种群数量都有精确统计', '观察点数量等于物种分布面积']::text[],1,'保护等级是特定评估年份、特定分类单元与特定区域的结论，必须标注来源与年份；观测点也不能等同于完整分布范围。',3,'数据素养','IUCN Red List','https://www.iucnredlist.org/','editorial') on conflict (id) do nothing;
insert into evolution_records (id,title,range_label,mya_start,mya_end,description,highlights,species_slugs,node_kind,source_name,source_url,review_status) values ('tl-01','寒武纪大爆发','约 538.8–485.4 百万年前',538.8,485.4,'显生宙的开端。海洋动物门类在相对短的时间内大量出现，化石记录中保存了大量具矿化骨骼的体型。现代动物门的基本蓝图可追溯至这一时期。',ARRAY['三叶虫繁盛', '节肢动物与软体动物多样化', '矿化骨骼出现']::text[],'{}'::text[],'era','Paleobiology Database','https://paleobiodb.org/','editorial') on conflict (id) do nothing;
insert into evolution_records (id,title,range_label,mya_start,mya_end,description,highlights,species_slugs,node_kind,source_name,source_url,review_status) values ('tl-02','泥盆纪 · 鱼类时代','约 419.2–358.9 百万年前',419.2,358.9,'鱼类高度多样化，肉鳍鱼类的演化支系最终产生了四足动物。提塔利克鱼（Tiktaalik）等过渡化石保存了鱼类与四足类之间的形态特征。',ARRAY['肉鳍鱼类繁盛', '四足动物起源', '早期森林形成']::text[],'{}'::text[],'fossil','Paleobiology Database','https://paleobiodb.org/','editorial') on conflict (id) do nothing;
insert into evolution_records (id,title,range_label,mya_start,mya_end,description,highlights,species_slugs,node_kind,source_name,source_url,review_status) values ('tl-03','二叠纪末大灭绝','约 251.9 百万年前',251.9,251.9,'地球上已知最严重的生物多样性危机之一，海洋与陆地生态系统受到重创。合弓纲（哺乳动物远祖所属支系）在此前后经历剧烈更替。',ARRAY['约八成以上海洋物种消失', '生态系统重组', '合弓纲与主龙类此后分化']::text[],'{}'::text[],'node','Paleobiology Database','https://paleobiodb.org/','editorial') on conflict (id) do nothing;
insert into evolution_records (id,title,range_label,mya_start,mya_end,description,highlights,species_slugs,node_kind,source_name,source_url,review_status) values ('tl-04','侏罗纪—白垩纪 · 恐龙与早期哺乳动物','约 201.4–66 百万年前',201.4,66,'恐龙占据陆地生态位，哺乳形类在夜间与小型生态位中演化。鸟类起源于兽脚类恐龙的证据在化石与系统发育分析中不断累积。',ARRAY['鸟类起源于兽脚类恐龙', '被子植物兴起', '哺乳形类多样化']::text[],'{}'::text[],'era','Open Tree of Life','https://tree.opentreeoflife.org/','editorial') on conflict (id) do nothing;
insert into evolution_records (id,title,range_label,mya_start,mya_end,description,highlights,species_slugs,node_kind,source_name,source_url,review_status) values ('tl-05','白垩纪末撞击事件','约 66 百万年前',66,66,'希克苏鲁伯撞击与大规模火山活动叠加，非鸟恐龙灭绝，鸟类与哺乳动物幸存并进入新的辐射演化阶段。',ARRAY['非鸟恐龙灭绝', '鸟类幸存', '哺乳动物辐射']::text[],'{}'::text[],'node','Paleobiology Database','https://paleobiodb.org/','editorial') on conflict (id) do nothing;
insert into evolution_records (id,title,range_label,mya_start,mya_end,description,highlights,species_slugs,node_kind,source_name,source_url,review_status) values ('tl-06','新生代 · 哺乳动物辐射','约 66–2.58 百万年前',66,2.58,'哺乳动物在体型、食性与运动方式上快速分化，鲸类回到海洋，灵长类在森林中演化。现代多数哺乳动物目在这一时期确立。',ARRAY['鲸类入海', '灵长类演化', '草原扩张']::text[],ARRAY['blue-whale', 'african-elephant', 'mountain-gorilla']::text[],'era','Open Tree of Life','https://tree.opentreeoflife.org/','editorial') on conflict (id) do nothing;
insert into evolution_records (id,title,range_label,mya_start,mya_end,description,highlights,species_slugs,node_kind,source_name,source_url,review_status) values ('tl-07','第四纪 · 冰期与巨型动物','约 2.58 百万年前至今',2.58,0,'反复的冰期与间冰期塑造了现代生物地理格局。大型动物在部分大陆经历灭绝，人类活动的影响逐步增强。',ARRAY['冰期循环', '大型动物区系变化', '人类扩散']::text[],ARRAY['emperor-penguin', 'snow-leopard', 'red-fox']::text[],'era','Paleobiology Database','https://paleobiodb.org/','editorial') on conflict (id) do nothing;
